(5, 'CM250', 'chemistry', 'CM250 is very very very very useful', '[\"Specs 1\", \"Specs 2\"]', '[\"Hey\", \"Now\"]', '[\"What\", \"When\"]', '[\"When\", \"I\", \"Do\"]', '[\"ISO 2518231\", \"Certified\"]', '[\"Reagent 1\", \"Reagent 2\"]', '[\"products/6kx01XEkRb9qybGqKl8bicQkW5yqiUyhupIGgTgf.jpg\", \"products/3WxTxqCPUKhXVoxGY30j47CnMucE1Rr1PtqDO8Ql.jpg\", \"products/D8FhuuILIUefklO17AIUa3GTRv8Qp5sQsZ9bzu6D.jpg\"]', 'products/6kx01XEkRb9qybGqKl8bicQkW5yqiUyhupIGgTgf.jpg', 0, 'brochures/GBSaTY85ukBXVCr5REfM5B6Bhxe6UakOA5qUZI8t.pdf', '2025-12-01 10:37:29', '2025-12-10 02:52:58', '2025-12-10 02:52:58'),
(6, 'ECLIA8000', 'immunology', 'The ECL8000 is a fully automated, high-performance immunoassay analyzer based on advanced Electro-chemiluminescence (ECLIA) technology. It delivers high-precision results for a wide range of clinical diagnostics and is engineered for reliability, speed, and ease of use in modern laboratories', '[\"Throughput: 86 Tests per hour\", \"Time to First Result: 9 minutes\", \"Methodology: Electro-chemiluminescence Immunoassay (ECLIA)\", \"Reagent Channels: 10 refrigerated positions\", \"Sample Positions: 30 (continuous loading)\", \"Sample Type: Serum, Plasma\"]', '[\"High-Sensitivity ECLIA Technology: Minimizes false results compared to enzymatic chemiluminescence.\", \"STAT Testing Capability: Prioritizes urgent samples without interrupting workflow.\", \"User-Friendly Operation: Features a touch screen interface and runs on a Windows 10 operating system.\", \"Integrated Barcode Scanning: Ensures accurate sample and reagent tracking.\", \"Automatic Dilution & Liquid Level Detection: Reduces manual steps and enhances process safety.\", \"Compact Footprint: Occupies minimal bench space (~0.4 m²), optimizing lab layout.\", \"Onboard Refrigerated Reagent Storage: Maintains 10 reagent bottles at 4-15°C\"]', '[\"Thyroid Function Testing\", \"Fertility and Reproductive Hormone Panels\", \"Tumor Marker Quantification\", \"Cardiac Marker Analysis\", \"Infectious Disease Serology\", \"Inflammation and Autoimmune Markers\", \"Bone Metabolism Studies\"]', '[\"Incubation Temperature: 37±0.5°C[citation:7]\", \"Probe System: Liquid level detection with crash protection[citation:7]\", \"Sample Volume Range: 5 – 100 µL[citation:7]\", \"Dimensions: 650 mm (H) x 620 mm (W) x 650 mm (D)\", \"Weight: 92 kg\"]', '[\"CE\", \"ISO\"]', '[\"Thyroid Profile Assay Kit\", \"Fertility Hormone Panel Kit\", \"Tumor Marker Assay Kit (e.g., AFP, CEA, PSA)\", \"Cardiac Marker Assay Kit (e.g., Troponin I, NT-proBNP)\", \"Inflammation Marker Kit (e.g., CRP, Procalcitonin)\", \"Infectious Disease Serology Kit\", \"Bone Metabolism Marker Kit (e.g., Vitamin D, PTH)\"]', '[\"products/yWqguw6fYTWhOIPP4vcEkvpl4wD3j6MTFkRiq19y.jpg\", \"products/FtZMKzrQufdqrJGBeNcSwFz5XRDuaCdwm1Ar2k9V.png\"]', 'products/yWqguw6fYTWhOIPP4vcEkvpl4wD3j6MTFkRiq19y.jpg', 0, 'brochures/WiX3w7weVGsf8FLpIezjpRdHkenSvUm8xYOygpPI.pdf', '2025-12-05 06:21:12', '2025-12-15 21:32:02', NULL),
(7, 'CM250', 'chemistry', 'The CM250 Chemistry Analyzer is a compact, automated clinical chemistry analyzer designed for routine biochemical testing in small- to medium-sized laboratories, clinics, and hospitals. It supports high-throughput, reliable analysis while maintaining a relatively small footprint.', '[\"Fully automated operation for routine clinical chemistry assays\",\"Photometric analysis using standard biochemical methods\",\"High processing speed, suitable for daily diagnostic workloads\",\"User-friendly interface for easy operation and result management\",\"Low sample and reagent consumption, helping reduce operating costs\",\"Supports a wide test menu, including liver, kidney, lipid, and metabolic panels\",\"Built-in quality control and calibration functions for accurate results\"]', '[\"Type: Fully automatic, random access chemistry analyzer.\",\"Throughput: Up to 230 tests\\/hour.\",\"Sample positions: 48\",\"Reagent positions: 48 (Peltier cooled)\",\"Reaction cuvettes: 80\",\"Sample volume: ~2\\u2013100 \\u00b5L\"]', '[\"Clinical diagnostics\",\"Routine biochemical testing\",\"Health checkups and screening laboratories\"]', '[\"Optical system: Double-beam photometer.\",\"Wavelengths: 340\\u2013767 nm.\",\"Methods: Endpoint, kinetics, turbidimetry.\",\"STAT samples: Yes\",\"Dimensions: ~85 \\u00d7 58 \\u00d7 48 cm\",\"Power: 85\\u2013240 VAC\"]', '[\"\\u2022 CE marked\",\"\\u2022 ISO 13485\",\"\\u2022 ANMAT approved\"]', '[\"Glucose\",\"Urea\",\"Creatinine (Jaffe \\/ Enzymatic)\",\"Uric Acid\",\"Total Protein\",\"Albumin\",\"Bilirubin Total\",\"Bilirubin Direct\",\"Cholesterol Total\",\"HDL Cholesterol\",\"LDL Cholesterol\",\"Triglycerides\",\"AST (SGOT)\",\"ALT (SGPT)\",\"Alkaline Phosphatase (ALP)\",\"Gamma GT (GGT)\",\"LDH\",\"CK\",\"Calcium\",\"Phosphorus\",\"Magnesium\",\"Iron\",\"Amylase\",\"Lipase\",\"Controls and Calibrators (multi-parameter)\",\"Wash\\/Cleaning Solution\"]', '[\"products\\/7mOmusVd4UnzqKBTbTOHY9VHQD4p0hgUBkbLve0O.jpg\"]', 'products/7mOmusVd4UnzqKBTbTOHY9VHQD4p0hgUBkbLve0O.jpg', 0, 'brochures/Yyrk0aDqUNvwCDqLlD1Srkp2lg3X0QDh7TX8KpvX.pdf', '2026-01-07 15:58:20', '2026-01-07 15:59:23', NULL),
(8, 'MEK 1302- CELLTAC ALPHA HEMATOLOGY ANALYZER', 'hematology', 'The Celltac α MEK-1302 is a compact, automated 3-part differential hematology analyzer used in clinical labs to perform Complete Blood Count (CBC) and white blood cell differential tests with high precision and efficiency. It’s part of the Celltac α series manufactured by Nihon Kohden.', '[\"Type: Automated hematology analyzer (3-part WBC differential)\",\"Parameters: CBC + 3-part diff + research indices (~23 total)\",\"Methods: Impedance (WBC\\/RBC\\/PLT), Colorimetric (HGB)\",\"Modes: Open, Closed (cap-piercing), Capillary\",\"Throughput: ~60 samples\\/hour\",\"Sample volume: 20 \\u00b5L\",\"Reproducibility: WBC \\u22642%, RBC\\/HGB \\u22641.5%, PLT \\u22644%\",\"Size\\/Weight: 230 \\u00d7 450 \\u00d7 428 mm, ~20 kg\",\"Power: 100\\u2013240 V AC, 150 VA\",\"Environment: 15\\u201330\\u00b0C, 30\\u201385% humidity\",\"Memory: ~50,000 results with histograms\"]', '[\"performs CBC + 3-part WBC differential\",\"DynaHelix Flow technology for accurate cell counting\",\"Closed-tube sampling with cap-piercing (safer handling)\",\"Color-coded rerun alerts (Smart ColoRerun Assist)\",\"Built-in quality control with Westgard rules\",\"Throughput: ~60 samples\\/hour\",\"Sample volume: ~20 \\u00b5L\",\"Compact benchtop design suitable for small\\/medium labs\"]', '[\"Routine Complete Blood Count (CBC) testing\",\"3-part WBC differential (lymphocytes, monocytes, granulocytes)\",\"Detection and monitoring of anemia, infections, and blood disorders\",\"Patient follow-up during treatment or disease management\",\"Use in hospitals, diagnostic centers, and clinical labs\",\"Helpful research indices (e.g., Mentzer Index, NLR) for clinical evaluation\"]', '[\"\\u2022 Type: Automated hematology analyzer (3-part differential)\",\"\\u2022 Parameters: CBC + 3-part WBC diff + research indices (\\u224823 total)\",\"\\u2022 Methods: Impedance (WBC\\/RBC\\/PLT), Colorimetric (HGB)\",\"\\u2022 Throughput: ~60 samples\\/hour\",\"\\u2022 Sample volume: ~20 \\u00b5L\",\"\\u2022 Modes: Open, Closed (cap-piercing), Capillary\",\"Performance\",\"\\u2022 WBC repeatability \\u22642.0%\",\"\\u2022 RBC \\u22641.5% | HGB \\u22641.5% | PLT \\u22644.0%\",\"Physical\",\"\\u2022 Size: 230 \\u00d7 450 \\u00d7 428 mm\",\"\\u2022 Weight: ~20 kg\",\"Power\",\"\\u2022 100\\u2013240 V AC, 50\\/60 Hz\",\"Operating Conditions\",\"\\u2022 Temp: 15\\u201330 \\u00b0C\",\"\\u2022 Humidity: 30\\u201385%\",\"Data Storage\",\"\\u2022 Memory: ~50,000 results with histograms\"]', '[\"Medical device registered (e.g., Taiwan license)\",\"IVD compliant (CE\\/IVDR where applicable)\",\"Manufactured under ISO\\u202f9001 & ISO\\u202f13485 quality standards\"]', '[\"Diluent \\/ Lyse Solution: For WBC\\/RBC\\/PLT measurement\",\"HGB Reagent: Colorimetric hemoglobin measurement\",\"Controls \\/ QC Reagents: For quality checks (Westgard rules compatible)\",\"Capillary \\/ Closed-Tube Accessories: For safe sample processing\",\"Shelf Life: Typically 12\\u201324 months depending on reagent\"]', '[\"products\\/vIaMgfzeVN7y7JHdXOApr0csCdbfrvaQA0syAUeC.png\"]', 'products/vIaMgfzeVN7y7JHdXOApr0csCdbfrvaQA0syAUeC.png', 0, NULL, '2026-01-30 14:31:21', '2026-01-30 14:31:21', NULL),
(9, 'AEHEALTH LAMUNO PRO', 'immunology', 'The AEHealth Lamuno Pro is a 12‑channel fluorescence immunoassay analyzer used for quantitative immunodiagnostic testing. It features independent multi‑item detection, automatic incubation and readout, and a 10.1″ touchscreen interface. The system supports 60+ test items with results in about 3–15 minutes, barcode recognition, and automatic data transfer to HIS/LIS systems, plus real‑time printing and quality control functions for reliable clinical use.', '[\"Channels: 12 independent\",\"Display: 10.1\\u2033 touchscreen\",\"Size: 417 \\u00d7 296 \\u00d7 156\\u202fmm | Weight: ~5.3\\u202fkg\",\"Interfaces: USB, RS\\u2011232\",\"Test items: >60 (barcode recognition)\",\"Result time: 3\\u201315\\u202fmin\",\"Repeatability: \\u22643% | Accuracy: \\u226415% | Linearity: \\u22650.99\",\"Features: Automatic incubation, detection, result interpretation, HIS\\/LIS upload, thermal printing\"]', '[\"12 independent channels for multi\\u2011item testing\",\"10.1\\u2033 touchscreen with intuitive interface\",\"Automatic incubation, detection, and result interpretation\",\"Supports >60 tests with barcode recognition\",\"Results in 3\\u201315 minutes with HIS\\/LIS upload and auto\\u2011printing\"]', '[\"Clinical diagnostics for hospitals and labs\",\"Infectious disease testing (e.g., viral and bacterial markers)\",\"Immunoassays for hormones, antibodies, and other biomarkers\",\"Point-of-care testing (POC) or central lab use\",\"Rapid screening and patient monitoring\"]', '[\"\\u2022 Dimensions: 417 \\u00d7 296 \\u00d7 156 mm\",\"\\u2022 Weight: ~5.28 kg\",\"\\u2022 Display: 10.1\\u2033 HD touchscreen\",\"\\u2022 Interfaces: USB, RS\\u2011232\",\"\\u2022 Printing: Thermal printer support\",\"\\u2022 Repeatability: \\u2264 3%\",\"\\u2022 Accuracy: \\u2264 15%\",\"\\u2022 Linearity: \\u2265 0.99\",\"\\u2022 Channel consistency: \\u2264 3%\",\"\\u2022 Channels: 12 independent\",\"\\u2022 Test items: > 60 with barcode recognition\",\"\\u2022 Result time: ~3\\u201315 min\",\"\\u2022 Automatic features: Incubation, detection, result interpretation, HIS\\/LIS upload\"]', '[\"ISO\\u202f13485 certified (IVD quality management)\",\"CE Mark for European IVD compliance\",\"NGSP certified for HbA1c testing\"]', '[\"Cardiac: cTnI, CK\\u2011MB, D\\u2011Dimer, NT\\u2011proBNP, Myoglobin, sST2\",\"Tumor: AFP, CEA, Ferritin, PSA, CA125, CA153, CA19\\u20119\",\"Inflammation: Hs\\u2011CRP, CRP, PCT, SAA, IL\\u20116\",\"Hormones: \\u03b2\\u2011HCG, LH, FSH, E2, AMH, Testosterone, Progesterone, PRL\",\"Thyroid: T3, T4, FT3, FT4, TSH\",\"Infectious disease: HBsAg, HCV, COVID\\u201119 Antigen\\/Antibody\",\"Others: Renal, digestive, miscellaneous biomarkers\"]', '[\"products\\/6kZOZAqfU0uuewbkF2ERXFf0j3nz7soJrNnH2pUX.jpg\"]', 'products/6kZOZAqfU0uuewbkF2ERXFf0j3nz7soJrNnH2pUX.jpg', 0, NULL, '2026-01-30 15:25:31', '2026-01-30 15:25:31', NULL),
(10, 'Celltac G+ (MEK-9200)', 'hematology', 'Automated hematology analyzer with 5-part WBC differential, reticulocyte analysis, dual-laser counting, ~90 tests/hour, barcode reading, HL7/LIS connectivity, and ~31 clinical parameters.', '[\"Technology: Dual-laser (DynaScatter + HEM488) with DynaHelix Flow\",\"Parameters: 31 clinical + 8 research (incl. reticulocytes)\",\"Throughput: ~90 tests\\/hr (CBC+DIFF), ~55 tests\\/hr (with RET)\",\"Sample volume: 32\\u201347\\u202f\\u00b5L\",\"Loading: Rack system with barcode & automatic mixing\",\"Memory: 50,000 results\",\"Connectivity: HL7\\/LIS\",\"Size\\/Weight: 675 \\u00d7 576 \\u00d7 589\\u202fmm, ~76\\u202fkg\"]', '[\":5\\u2011part WBC differential + reticulocyte analysis\",\":Dual\\u2011laser technology (improved scatter & fluorescence)\",\":High throughput: ~90 tests\\/hour (CBC+DIFF)\",\":Automatic sample mixing & barcode reader\",\":Large memory (up to ~50,000 results)\",\":HL7\\/LIS connectivity for lab systems\",\":Rack loading for efficient workflow\"]', '[\":Routine complete blood count (CBC) testing\",\":5\\u2011part WBC differential for detailed leukocyte profiling\",\":Reticulocyte analysis for anemia and bone marrow function assessment\",\":Patient monitoring in hospitals, clinics, and diagnostic labs\",\":High\\u2011volume lab workflows requiring fast throughput and connectivity\"]', '[\"Technology: DynaScatter Laser + HEM488 & DynaHelix Flow (laser scatter + fluorescence)\",\"Parameters: 31 clinical + 8 research (incl. reticulocytes)\",\"Throughput: ~90 tests\\/hr (CBC + DIFF), ~55 tests\\/hr (with RET)\",\"Sample volume: CBC 32\\u202f\\u00b5L; CBC+DIFF+RET 47\\u202f\\u00b5L\",\"Sample loading: Rack system (10 tubes\\/rack), automatic mixing & barcode reader\",\"Memory: Up to 50,000 results\",\"Connectivity: HL7 protocol for LIS integration\",\"Size\\/Weight: 675 \\u00d7 576 \\u00d7 589\\u202fmm, ~76\\u202fkg\"]', '[\":Medical device registered (e.g., Malaysia)\",\":ISO 13485 \\/ ISO\\u202f9001 compliant\",\":CE\\u2011marked \\/ IVD compliant\"]', '[\"DILUENT (for sample dilution)\",\"Hemolyzing reagents (e.g., Hemolynac series)\",\"Cleaning\\/detergent reagents (e.g., Cleanac\\/Cleaner series)\",\"Reticulocyte stain reagents (for fluorescence\\/RET measurement)\",\"Control reagents (for QC checks)\",\"Calibrators\"]', '[\"products\\/ZsuOWEDMV5xYAO4E8et9qR18nOI2R9A44BqKIfVN.png\"]', 'products/ZsuOWEDMV5xYAO4E8et9qR18nOI2R9A44BqKIfVN.png', 0, NULL, '2026-01-30 17:16:34', '2026-01-30 17:16:34', NULL),
(11, 'AEHEALTH LAMUNOX', 'immunology', 'Portable fluorescence immunoassay analyzer for rapid (3–15 min) quantitative testing of hormones, cardiac, thyroid, inflammation, and infectious markers; compact, easy-to-use, suitable for labs and POC.', '[\"Dimensions: 269 \\u00d7 130 \\u00d7 137 mm\",\"Weight: ~1.5 kg\",\"Display: 7\\u2033 high\\u2011resolution touchscreen\",\"Data Storage: ~8,000 test results\",\"Power: AC 100\\u2013240\\u202fV, 50\\/60\\u202fHz, 36\\u202fW\",\"Data Output: Onboard screen \\/ printer \\/ PC \\/ LIS\",\"QC Code Reading: RFID\",\"Test Types Supported: Thyroid, hormone panel, cardiac markers, inflammation, renal\\/digestive markers, tumor markers, allergies, infectious markers, COVID\\u201119, HbA1c, 25\\u2011OH\\u2011VD\"]', '[\"Portable and compact design (~1.5\\u202fkg)\",\"Fluorescence immunoassay for quantitative results\",\"Rapid results (~3\\u201315\\u202fminutes)\",\"7\\u2033 touchscreen with simple interface\",\"Supports wide test menu (cardiac, hormones, thyroid, inflammation, infectious, etc.)\",\"Multiple output options (screen, printer, PC\\/LIS)\",\"Built\\u2011in RFID QC code reading\"]', '[\"Clinical diagnostics in hospitals and labs\",\"Point\\u2011of\\u2011care testing (POC)\",\"Cardiac marker screening\",\"Hormone & thyroid testing\",\"Inflammation & infectious marker detection\",\"Metabolic and wellness panels (e.g., diabetes, vitamin D)\"]', '[\"\\u2022 Dimensions: 269 \\u00d7 130 \\u00d7 137 mm\",\"\\u2022 Weight: ~1.5 kg\",\"\\u2022 Display: 7\\u2033 high\\u2011resolution touchscreen\",\"\\u2022 Data storage: ~8,000 results\",\"\\u2022 Power: AC 100\\u2013240\\u202fV, 50\\/60\\u202fHz, 36\\u202fW\",\"\\u2022 Data output: Onboard screen, printer, PC\\/LIS\\/HIS\",\"\\u2022 QC code reading: RFID\",\"\\u2022 Repeatability: CV \\u2264 3%\",\"\\u2022 Test time: ~3\\u201315 minutes (varies by assay)\"]', '[\"ISO\\u202f13485 certified\",\"CE \\/ IVD compliant\",\"NGSP certified for HbA1c\"]', '[\"Thyroid: T3, T4, TSH, FT3, FT4\",\"Hormones: \\u03b2\\u2011HCG, LH, FSH, PRL, Testosterone, Progesterone, AMH, Cortisol\",\"Cardiac markers: cTnI, cTnT, Myoglobin, CK\\u2011MB, D\\u2011Dimer, NT\\u2011proBNP, CK\\u2011MB\\/cTnI\\/Myo, sST2\",\"Inflammation: HsCRP + CRP, PCT, SAA, IL\\u20116\",\"Renal: NGAL, Urine microalbumin (MAU)\",\"Digestive: Gastrin\\u201117 (G17), Pepsinogen I\\/II (PGI\\/PGII), Fecal occult blood (FOB), Calprotectin (Cal)\",\"Tumor markers: Ferritin, PSA, CEA, AFP, CA125, CA153, CA199, fPSA\",\"Allergy: IgE\",\"Infectious: HCV antibody, HBsAg, HIV antigen\\/antibody\",\"COVID\\u201119: Neutralizing antibody, Antigen\",\"Others: HbA1c, 25\\u2011OH\\u2011Vitamin\\u202fD\"]', '[\"products\\/rl4zDTpmFQFowxoaz6Ww7cDl0n8qOrEFOzh8KTsy.jpg\"]', 'products/rl4zDTpmFQFowxoaz6Ww7cDl0n8qOrEFOzh8KTsy.jpg', 0, NULL, '2026-01-30 17:35:10', '2026-01-30 17:35:10', NULL),
(12, 'CELLTAC G', 'hematology', 'Celltac G is a fully-automated hematology analyzer designed for clinical laboratories to measure and report blood cell components and related parameters. It’s manufactured by Nihon Kohden, a well-known medical equipment company', '[\"\\u2022 5-part hematology analyzer\",\"\\u2022 90 tests\\/hour\",\"\\u2022 33 parameters (CBC + diff)\",\"\\u2022 Sample: 25\\u201340 \\u00b5L\",\"\\u2022 Laser + flow technology\",\"\\u2022 Continuous rack loading, STAT mode\",\"\\u2022 10.4\\u2033 touchscreen\",\"\\u2022 ~10,000 results storage\",\"\\u2022 Size: 675 \\u00d7 576 \\u00d7 589 mm | Weight: ~66 kg\",\"\\u2022 Nihon Kohden, Japan\"]', '[\"\\u2022 5-part WBC differential\",\"\\u2022 Up to 90 tests per hour\",\"\\u2022 Continuous rack loading (walk-away operation)\",\"\\u2022 Low sample volume (25\\u201340 \\u00b5L)\",\"\\u2022 Laser scatter + flow technology\",\"\\u2022 STAT and pediatric modes\",\"\\u2022 Barcode sample & reagent management\",\"\\u2022 Automatic mixing and aspiration\",\"\\u2022 Flagging of abnormal results\",\"\\u2022 10.4\\u2033 color touchscreen\"]', '[\"\\u2022 Routine Complete Blood Count (CBC) testing\",\"\\u2022 5-part WBC differential analysis\",\"\\u2022 Diagnosis and monitoring of anemia, infections, and blood disorders\",\"\\u2022 Hospital and clinical laboratory use\",\"\\u2022 Diagnostic centers and reference labs\",\"\\u2022 Pediatric and low-volume blood testing\",\"\\u2022 High-throughput routine hematology screening\"]', '[\"\\u2022 Analyzer type: Fully automatic 5-part hematology\",\"\\u2022 Throughput: 90 samples\\/hour\",\"\\u2022 Parameters: 33\",\"\\u2022 Sample volume: 25\\u201340 \\u00b5L\",\"\\u2022 Detection: Laser scatter + flow cytometry\",\"\\u2022 Display: 10.4\\u2033 color touchscreen\",\"\\u2022 Sample loading: Continuous rack system\",\"\\u2022 STAT mode: Available\",\"\\u2022 Data storage: ~10,000 results\",\"\\u2022 Dimensions: 675 \\u00d7 576 \\u00d7 589 mm\",\"\\u2022 Weight: ~66 kg\",\"\\u2022 Manufacturer: Nihon Kohden, Japan\"]', '[\"\\u2022 CE Mark (IVD Medical Device) \\u2013 complies with EU Directive 98\\/79\\/EC\",\"\\u2022 ISO 13485 \\u2013 Medical device quality management (manufacturer)\",\"\\u2022 ISO 14021 \\u2013 Environmental labeling (Green Product Label)\",\"\\u2022 EN 55011 Class B \\u2013 EMC compliance\",\"\\u2022 IVD (In-Vitro Diagnostic) certified\",\"\\u2022 Manufactured by Nihon Kohden, Japan\"]', '[\"\\u2022 Diluent\",\"\\u2022 Lyse reagent (WBC differential)\",\"\\u2022 Hemoglobin reagent\",\"\\u2022 Detergent \\/ Cleaner\",\"\\u2022 Rinse solution\"]', '[\"products\\/Cfnr5K1YSxStsDgaiH6ouFHQmOVajXbXPvy8anPd.jpg\"]', 'products/Cfnr5K1YSxStsDgaiH6ouFHQmOVajXbXPvy8anPd.jpg', 0, NULL, '2026-02-10 14:26:24', '2026-02-10 14:26:24', NULL),
(13, 'Celltac ES', 'hematology', 'Celltac ES (MEK‑7300) is a 5‑part differential hematology analyzer by Nihon Kohden, made for clinical labs to run complete blood counts (CBC) with advanced laser‑based analysis.', '[\"\\u2022 Parameters: 23 reportable + 2 research (WBC, RBC, HGB, HCT, MCV, MCH, MCHC, RDW, PLT, PCT, PDW, MPV + IG#, IG%)\",\"\\u2022 Throughput: approx. 60 samples\\/hour (open mode)\",\"\\u2022 Sample volume: CBC ~ 30\\u202f\\u00b5L, CBC+Diff ~ 55\\u202f\\u00b5L\",\"\\u2022 Display: 10.4\\u2033 color touchscreen with scattergrams\\/histograms\",\"\\u2022 Data storage: up to ~15,000 results (SD card)\",\"\\u2022 Dimensions: 382\\u202f\\u00d7\\u202f532\\u202f\\u00d7\\u202f465\\u202fmm\",\"\\u2022 Weight: approx. 35\\u202fkg\",\"\\u2022 Technology: DynaScatter laser optical differential\",\"\\u2022 Modes: Open, Closed, Pre\\u2011dilution, WBC high\\/low, Capillary (as low as ~10\\u202f\\u00b5L)\"]', '[\"\\u2022 5\\u2011part WBC differential using laser scatter\",\"\\u2022 Up to ~60 tests\\/hour throughput\",\"\\u2022 Multiple dilution modes (normal, pre\\u2011dilution, high\\/low WBC, capillary)\",\"\\u2022 Low sample volume (as little as ~10\\u201330\\u202f\\u00b5L)\",\"\\u2022 10.4\\u2033 color touchscreen with scattergrams\\/histograms\",\"\\u2022 Barcode support (samples\\/reagents)\",\"\\u2022 Automatic mixing and aspiration\",\"\\u2022 STAT and pediatric modes\",\"\\u2022 LIS connectivity and optional built\\u2011in printer\",\"\\u2022 Compact and lightweight design\"]', '[\"\\u2022 Routine Complete Blood Count (CBC) testing\",\"\\u2022 5\\u2011part WBC differential analysis\",\"\\u2022 Diagnosis and monitoring of anemia, infections, and blood disorders\",\"\\u2022 Hospitals, clinical laboratories, and diagnostic centers\",\"\\u2022 Pediatric and low-volume blood testing\",\"\\u2022 High-throughput routine hematology screening\"]', '[\"\\u2022 Parameters: 23 reportable + 2 research\",\"\\u2022 Throughput: ~60 samples\\/hour\",\"\\u2022 Sample volume: ~30\\u201355 \\u00b5L (capillary mode ~10 \\u00b5L)\",\"\\u2022 Technology: Laser scatter 5\\u2011part differential\",\"\\u2022 Display: 10.4\\u2033 color touchscreen\",\"\\u2022 Data storage: ~15,000 results\",\"\\u2022 Dimensions: 382 \\u00d7 532 \\u00d7 465 mm\",\"\\u2022 Weight: ~35 kg\",\"\\u2022 Modes: Normal, pre\\u2011dilution, high\\/low WBC, capillary\"]', '[\"\\u2022 CE Mark \\u2014 meets EU In\\u2011Vitro Diagnostic (IVD) medical device requirements (for sale\\/performance in Europe)\",\"\\u2022 ISO quality standards \\u2014 typically ISO (manufacturer quality compliance)\"]', '[\"Celltac ES \\u2013 Reagents List\",\"\\u2022 Isotonac 4 \\u2013 Diluent solution\",\"\\u2022 Hemolynac 3N \\u2013 Hemolyzing reagent for CBC\",\"\\u2022 Hemolynac 5 \\u2013 Hemolyzing reagent for differential\",\"\\u2022 Cleanac \\u2013 Detergent \\/ cleaner\",\"\\u2022 Cleanac 3 \\u2013 Secondary detergent \\/ cleaner\"]', '[\"products\\/FWbddPOfBDGtzlv9rpldPVBVuzic1CEXDddyACAB.jpg\"]', 'products/FWbddPOfBDGtzlv9rpldPVBVuzic1CEXDddyACAB.jpg', 0, NULL, '2026-02-10 14:33:42', '2026-02-10 14:33:42', NULL),
(14, 'WONDFO COAG UNIT', 'hematology', 'The Wondfo NX‑102 is a portable point‑of‑care optical coagulation analyzer that measures key clotting parameters such as PT/INR, APTT, Fibrinogen (FIB), ACT, and TT using a small whole blood sample (20 µL). It provides results in about 3–5 minutes on a touchscreen display and is designed for quick, reliable coagulation testing in clinical or veterinary settings.', '[\"\\u2022 Tests: PT\\/INR, APTT, TT, Fibrinogen (FIB), ACT\",\"\\u2022 Sample type: Citrated venous whole blood (capillary for PT\\/INR)\",\"\\u2022 Sample volume: 20\\u202f\\u00b5L\",\"\\u2022 Time to result: \\u2264\\u202f5 minutes\",\"\\u2022 Precision: CV \\u2264\\u202f5\\u202f%\",\"\\u2022 Display: 3.5\\u2033 touchscreen\",\"\\u2022 Memory: ~300 test results + 12 QC\",\"\\u2022 Connectivity: Ethernet\\/LIS; optional external printer\",\"\\u2022 Power: Rechargeable battery + AC adapter\",\"\\u2022 Dimensions: ~220 \\u00d7 175 \\u00d7 130\\u202fmm\",\"\\u2022 Weight: ~850\\u202fg (without battery)\",\"\\u2022 Environmental: 15\\u201335\\u202f\\u00b0C; 10\\u201390\\u202f% humidity\"]', '[\"\\u2022 Portable, lightweight, battery\\u2011operated\",\"\\u2022 Fast results (~3\\u20135\\u202fmin) with CV \\u22645%\",\"\\u2022 Tests: PT\\/INR, APTT, TT, FIB, ACT\",\"\\u2022 One-step operation with disposable reagent strips\",\"\\u2022 3.5\\u2033 touchscreen, Ethernet\\/LIS & printer support\",\"\\u2022 Stores ~300 results + QC records\"]', '[\"\\u2022 Screening of coagulation system function (PT\\/INR, APTT, TT, FIB, ACT) for clinical assessment\",\"\\u2022 Monitoring anticoagulant therapy (e.g., warfarin management)\",\"\\u2022 Monitoring thrombolytic therapy effectiveness\",\"\\u2022 Support in emergency, ICU, and operating room settings\",\"\\u2022 Used in anticoagulation clinics and ambulances for rapid point\\u2011of\\u2011care testing\"]', '[\"\\u2022 Tests: PT\\/INR, APTT, TT, Fibrinogen (FIB), ACT\",\"\\u2022 Sample type: Citrated venous whole blood (PT\\/INR also with capillary)\",\"\\u2022 Sample volume: 20\\u202f\\u00b5L\",\"\\u2022 Time to result: \\u2264\\u202f5\\u202fminutes\",\"\\u2022 Precision: CV \\u2264\\u202f5\\u202f%\",\"\\u2022 Display: 3.5\\u2033 color touchscreen\",\"\\u2022 Memory: Stores ~300 results + QC\",\"\\u2022 Connectivity: Ethernet\\/LIS support, external printer compatible\",\"\\u2022 Power: Rechargeable battery + AC adapter\",\"\\u2022 Dimensions: ~220 \\u00d7 175 \\u00d7 130\\u202fmm\",\"\\u2022 Weight: ~850\\u202fg\",\"\\u2022 Environmental: Operating ~15\\u201335\\u202f\\u00b0C, humidity 10\\u201390\\u202f%\",\"\\u2022 Certifications: CE & NMPA (IVD device)\"]', '[\"\\u2022 CE Mark (IVD) \\u2013 conforms to European in\\u2011vitro diagnostic device requirements\",\"\\u2022 NMPA (National Medical Products Administration, China) approval for medical device use\",\"\\u2022 ISO 13485 quality management system certification (manufacturer)\"]', '[\"Reagents \\/ Test Strips\",\"\\u2022 PT & INR reagent kit\",\"\\u2022 APTT reagent kit\",\"\\u2022 Fibrinogen (FIB) reagent kit\",\"\\u2022 Thrombin Time (TT) reagent kit\",\"\\u2022 Activated Clotting Time (ACT) reagent kit\"]', '[\"products\\/37BfqwSE6coHmt2rMFwSWyDednN6flw0OqIQ2aFP.jpg\"]', 'products/37BfqwSE6coHmt2rMFwSWyDednN6flw0OqIQ2aFP.jpg', 0, NULL, '2026-02-10 14:44:02', '2026-02-10 14:44:02', NULL),
(15, 'BIOWAY BW-300', 'microscopy', 'Bioway BW‑300 is a urine chemistry analyzer/strip reader that uses AI and computer vision technology to read urine test strips and provide rapid results.', '[\"\\u2022 Designed for urine analysis (10\\u201314 parameters) including: glucose, bilirubin, ketone, specific gravity, pH, blood, protein, urobilinogen, nitrite, leukocyte, creatinine, calcium ion, etc.\",\"\\u2022 Test speed: ~500+ tests\\/hour\",\"\\u2022 Display: 7\\u2033 large touchscreen (LCD)\",\"\\u2022 Display\\/print: Thermal printer + LCD\",\"\\u2022 Power: AC 100\\u2013240\\u202fV, 50\\u201360\\u202fHz\",\"\\u2022 Memory: Large internal storage for test results\",\"\\u2022 Connectivity: RS232, Wi\\u2011Fi, network, HIS\\/LIS support\",\"\\u2022 Weight: <5\\u202fkg\",\"\\u2022 Operating conditions: ~15\\u201335\\u202f\\u00b0C, humidity \\u226485%\"]', '[\"\\u2022 Uses AI + computer vision for accurate urine strip reading\",\"\\u2022 Compatible with 10\\u201314 parameter urine strips (GLU, BIL, KET, pH, PRO, BLD, SG, LEU, NIT, URO, VC, CRE, CAL, MAL)\",\"\\u2022 Fast test speed (~500+ tests\\/hour)\",\"\\u2022 7\\u2033 touchscreen display with thermal printing\",\"\\u2022 Large memory for storing test results (millions)\",\"\\u2022 Connectivity: RS232, Wi\\u2011Fi, network, HIS\\/LIS support\",\"\\u2022 Lightweight & portable (<5\\u202fkg)\"]', '[\"\\u2022 Routine urinalysis in clinics, hospitals, and labs\",\"\\u2022 Screening for urinary tract infections, kidney disorders, diabetes, and liver diseases\",\"\\u2022 Quick point-of-care urine strip analysis for large sample volumes\",\"\\u2022 Used in laboratory, emergency, or outpatient settings\"]', '[]', '[\"\\u2022 CE Mark \\u2013 meets European IVD medical device standards\",\"\\u2022 ISO 13485 \\u2013 quality management system for medical devices\",\"\\u2022 EU distributor certificate (European distribution compliance)\"]', '[\"\\u2022 Glucose (GLU)\",\"\\u2022 Bilirubin (BIL)\",\"\\u2022 Ketone (KET)\",\"\\u2022 pH\",\"\\u2022 Protein (PRO)\",\"\\u2022 Blood (BLD)\",\"\\u2022 Specific Gravity (SG)\",\"\\u2022 Leukocyte (LEU)\",\"\\u2022 Nitrite (NIT)\",\"\\u2022 Urobilinogen (URO)\",\"\\u2022 Creatinine (CRE)\",\"\\u2022 Calcium (CAL)\",\"\\u2022 Vitamin C (VC)\",\"\\u2022 Maltose (MAL)\"]', '[\"products\\/sbPAAwcQS2t4PMP3bYIv9vp9nUC8JnooA7qqKiwj.jpg\"]', 'products/sbPAAwcQS2t4PMP3bYIv9vp9nUC8JnooA7qqKiwj.jpg', 0, NULL, '2026-02-10 15:42:41', '2026-02-10 15:42:41', NULL),
(16, 'Sedimax Lite', 'microscopy', 'A semi‑automated urine sediment microscopy analyzer that produces full microscopic images of urine sediment and automatically classifies & counts particles, improving accuracy and speed while reducing manual microscopy work. It’s ideal for clinical labs, small labs, emergency departments, and as a backup to automated analyzers.', '[\"\\u2022 Operation: Semi\\u2011automatic urine sediment microscopy\",\"\\u2022 Throughput: Up to 60 samples\\/hour (operator\\u2011dependent)\",\"\\u2022 Memory: Up to 10,000 measurements with images\",\"\\u2022 Dilution factor: 1\\u2013100 setting available\",\"\\u2022 Sample volume: 175\\u202f\\u00b5L\",\"\\u2022 Size: 315\\u202f\\u00d7\\u202f320\\u202f\\u00d7\\u202f330\\u202fmm (W\\u00d7D\\u00d7H)\",\"\\u2022 Weight: ~13.5\\u202fkg\",\"\\u2022 Power: 100\\u2013240\\u202fV AC, 50\\u201360\\u202fHz\",\"\\u2022 Operating temp: 15\\u201330\\u202f\\u00b0C\",\"\\u2022 Operating humidity: 20\\u201380\\u202f%\",\"\\u2022 Storage temp: \\u201320 to 60\\u202f\\u00b0C\",\"\\u2022 Cuvette pack: 600 total (12 holders \\u00d7 50)\",\"\\u2022 Max cuvette load: 50 pcs (1 holder)\",\"\\u2022 Centrifuge speed\\/time: 2000\\u202fRPM for 10\\u202fs\",\"\\u2022 Images per sample: 15 full\\u2011field images\",\"\\u2022 Image size: 1280 \\u00d7 960 pixels\",\"\\u2022 Viewed field volume: \\u2248 0.15\\u202f\\u00b5L native urine\"]', '[\"\\u2022 Semi\\u2011automated urine sediment analysis with full field imaging\",\"\\u2022 Automatically classifies sediment particles (e.g., cells, casts, crystals)\",\"\\u2022 Manual microscopy mode for live viewing and moving microorganisms\",\"\\u2022 User\\u2011friendly software for results and reporting\",\"\\u2022 No liquid reagents or calibrators needed (cost\\u2011effective)\"]', '[\"\\u2022 Clinical urine sediment examination in labs and hospitals\",\"\\u2022 Emergency departments and small lab workflows\",\"\\u2022 Backup system for automated sediment analyzers\"]', '[]', '[\"\\u2022 Manufactured by A. Menarini Diagnostics, a company certified to ISO\\u202f9001:2015 and ISO\\u202f13485:2021 quality standards for medical devices (lab instruments and diagnostics)\",\"\\u2022 In\\u2011Vitro Diagnostic (IVD) medical device\\u2014designed and marketed for clinical sediment analysis (professional diagnostic use)\"]', '[\"\\u2022 Cuvettes (for sample loading)\",\"\\u2022 Slides \\/ Chamber cartridges (disposable)\",\"\\u2022 SediMAX\\u202fLITE Centrifuge Cups (disposable)\",\"\\u2022 Distilled water (for rinsing)\",\"\\u2022 Cleaning solution (for periodic maintenance)\"]', '[\"products\\/cy2I9gQ5N9bnvR05ff8cDLNkSXz6AHIXvw0qAspd.jpg\"]', 'products/cy2I9gQ5N9bnvR05ff8cDLNkSXz6AHIXvw0qAspd.jpg', 0, NULL, '2026-02-10 16:05:27', '2026-02-10 16:05:27', NULL),
(17, 'ELAN 30-ERBA', 'immunology', 'The ERBA ELAN 30s is a fully automated, bench-top ELISA microstrip processor designed to streamline ELISA testing in clinical laboratories. It can run up to six different assays in a single batch using 30 microstrip plates (240 wells) and provides walk-away automation from pipetting and incubation to washing and reading. Its intuitive software and real-time dashboard guide users through setup and monitoring, making it ideal for small to medium throughput labs that need reliable immunoassay processing without extensive manual steps', '[\"\\u2022 Assays per batch: Up to 6 different ELISA tests\",\"\\u2022 Microwells: 30 \\u00d7 8 = 240 wells\",\"\\u2022 Sample tube size: 12\\u201313 mm \\u00d7 75 mm (5 mL)\",\"\\u2022 Reagent bottles: 24 \\u00d7 20 mL + 30 \\u00d7 1.5 mL controls\\/calibrators\",\"\\u2022 Reader: 400\\u2013800 nm wavelength, single & dual mode, ~20 sec\\/strip\",\"\\u2022 Precision: < 1 % CV (0.5\\u20132.0 OD)\",\"\\u2022 Washer: 8 channels aspiration + 8 dispense, residual < 6 \\u00b5L\",\"\\u2022 Incubator: Programmable (37 \\u00b0C or RT), temp accuracy \\u00b1 1 \\u00b0C\",\"\\u2022 Pipetting: Fixed needle or disposable tips (5\\u2013200 \\u00b5L)\",\"\\u2022 Dimensions: ~1058 \\u00d7 520 \\u00d7 533 mm\",\"\\u2022 Weight: ~65 kg (shipping ~95 kg)\",\"\\u2022 Power: AC 110\\u2013240 V, 50\\/60 Hz, ~300 W\",\"\\u2022 Software: Quantitative & qualitative data, QC reports (Levey-Jennings, Westgard)\"]', '[\"\\u2022 Fully automated ELISA processing (pipetting, incubation, washing, reading)\",\"\\u2022 Runs up to 6 tests per batch on 240-well microstrips\",\"\\u2022 Built-in incubator & shaker for controlled reactions\",\"\\u2022 Integrated reader (400\\u2013800 nm) with fast read time (~20 sec\\/strip)\",\"\\u2022 Flexible reagent capacity (24 \\u00d7 20 mL + controls\\/calibrators)\",\"\\u2022 Adjustable wash cycles with multi-channel aspiration\\/dispense\",\"\\u2022 User-friendly software with QC reporting (Levey-Jennings\\/Westgard)\",\"\\u2022 Compact bench-top design for small-to-mid throughput labs\"]', '[\"\\u2022 Automated ELISA immunoassays in clinical diagnostic labs\",\"\\u2022 Screening of infectious diseases (HIV, HBV, HCV, Syphilis, Dengue, etc.)\",\"\\u2022 Hormone and tumor marker ELISA testing\",\"\\u2022 Autoimmune and inflammation markers assays\",\"\\u2022 Blood bank \\/ serology panels\",\"\\u2022 Small to mid-throughput lab workflows that require batch ELISA testing\"]', '[]', '[\"\\u2022 CE Mark (IVD) \\u2014 indicates the analyzer meets European in-vitro diagnostic device requirements.\",\"\\u2022 Manufacturer is part of Erba\\/Transasia, a company certified with ISO 13485:2016 (medical device quality management).\",\"\\u2022 Company also holds ISO 9001:2015 quality management certification\"]', '[\"\\u2022 ErbaLisa\\u00ae HIV Gen 4 \\u2013 HIV-1 p24 & antibody ELISA\",\"\\u2022 ErbaLisa\\u00ae HIV Gen 3 \\u2013 HIV-1\\/2 antibody ELISA\",\"\\u2022 ErbaLisa\\u00ae PICO HBsAg \\u2013 Ultra-sensitive Hepatitis B surface antigen ELISA\",\"\\u2022 ErbaLisa\\u00ae SEN HBsAg \\u2013 Hepatitis B surface antigen ELISA\",\"\\u2022 ErbaLisa Syphilis \\u2013 Syphilis antibody ELISA\",\"\\u2022 ErbaLisa Dengue NS1 Ag \\u2013 Dengue NS1 antigen ELISA\",\"\\u2022 ErbaLisa Dengue IgM \\u03bc-Capture \\u2013 Dengue IgM ELISA\",\"\\u2022 ErbaLisa Dengue IgG Capture \\u2013 Dengue IgG ELISA\",\"\\u2022 ErbaLisa\\u00ae COVID-19 IgG \\u2013 SARS-CoV-2 IgG antibody ELISA\",\"\\u2022 ErbaLisa\\u00ae Total Triiodothyronine (tT3) \\u2013 T3 hormone ELISA\",\"\\u2022 ErbaLisa\\u00ae Total Thyroxine (tT4) \\u2013 T4 hormone ELISA\",\"\\u2022 ErbaLisa\\u00ae Thyroid stimulating Hormone (TSH) \\u2013 TSH ELISA\",\"\\u2022 ErbaLisa\\u00ae HCV Gen3 V2 \\u2013 HCV antibody ELISA\",\"\\u2022 ErbaLisa\\u00ae HCV Gen 4 Ag + Ab \\u2013 Hepatitis C core antigen + antibody ELISA\"]', '[\"products\\/xB2bbxRiidz2sbX6XtNGTtoMdZZJT56XcD6IRVHu.jpg\"]', 'products/xB2bbxRiidz2sbX6XtNGTtoMdZZJT56XcD6IRVHu.jpg', 0, NULL, '2026-02-11 14:20:18', '2026-02-11 14:20:18', NULL),
(18, 'AEHEALTH LAMUNOX', 'immunology', 'AEHealth’s Lamuno series are portable immunofluorescence analyzers used in clinical labs to quantify biomarkers in blood or urine using fluorescence reagents. They offer real-time testing, simple operation, and broad analyte coverage including hormones, cardiac markers, tumor markers, inflammation markers, and more. The units are in-vitro diagnostic instruments used in hospitals, clinics, labs, and emergency/POC settings.', '[\"\\u2022 Type: Fluorescence immunoassay analyzer (portable)\",\"\\u2022 Dimensions: 269 \\u00d7 130 \\u00d7 137 mm\",\"\\u2022 Weight: ~1.5 kg\",\"\\u2022 Display: 7\\u2033 high-resolution touchscreen\",\"\\u2022 Data storage: ~8,000 test results\",\"\\u2022 Power: AC 100\\u2013240 V, 50\\/60 Hz; built-in battery (\\u22488 h)\",\"\\u2022 Data output: Onboard screen \\/ printer \\/ PC \\/ LIS\\/HIS\",\"\\u2022 Rated power: ~36 W\",\"\\u2022 QC code reading: RFID\",\"\\u2022 Repeatability: < 3 % (typical)\"]', '[\"\\u2022 High accuracy with real-time quantitative results\",\"\\u2022 Simple operation with 7\\u2033 high-resolution touchscreen\",\"\\u2022 Portable & lightweight design with built-in battery for >8 h use\",\"\\u2022 Supports many immunoassays (thyroid, hormones, cardiac, inflammation, infectious markers, tumor markers, COVID-19, etc.)\",\"\\u2022 Wireless operation and flexible data output (screen \\/ printer \\/ PC \\/ LIS\\/HIS)\",\"\\u2022 Instant results with high throughput test capability\",\"\\u2022 RFID QC code reading for quality control and traceability\"]', '[\"\\u2022 Quantitative immunofluorescence testing of blood and urine analytes.\",\"\\u2022 Hormone assays (e.g., thyroid, reproductive hormones).\",\"\\u2022 Cardiac markers (e.g., cTnI, NT-proBNP, D-Dimer).\",\"\\u2022 Inflammation & infection markers (CRP, PCT, IL-6, HBV, HCV, HIV).\",\"\\u2022 Tumor markers (CEA, AFP, PSA, CA125, CA199).\",\"\\u2022 COVID-19 antigen\\/antibody and other specialized assays.\",\"\\u2022 Used in clinical labs, hospitals, emergency\\/POC settings, and health screening centers.\"]', '[\"\\u2022 Dimensions: 269 \\u00d7 130 \\u00d7 137\\u202fmm\",\"\\u2022 Weight: ~1.5\\u202fkg\",\"\\u2022 Display: 7\\u2033 high\\u2011resolution touchscreen\",\"\\u2022 Data storage: ~8,000 test results\",\"\\u2022 Power: AC 100\\u2013240\\u202fV, 50\\/60\\u202fHz\",\"\\u2022 Rated power: ~36\\u202fW\",\"\\u2022 Battery working time: >\\u202f8\\u202fhours\",\"\\u2022 Data output: Onboard screen \\/ printer \\/ PC \\/ LIS\\/HIS\",\"\\u2022 QC code reading: RFID support\",\"\\u2022 Repeatability: <\\u202f3\\u202f%\"]', '[\"\\u2022 CE Mark (IVD) \\u2013 meets European in\\u2011vitro diagnostic device regulatory standards.\",\"\\u2022 ISO\\u202f13485 Quality Management \\u2013 the manufacturer operates under an ISO\\u202f13485 certified quality system for medical devices (including Lamuno products).\",\"\\u2022 NGSP Certification \\u2013 Lamuno series analyzers (including Lamuno X) have achieved certification from the National Glycohemoglobin Standardization Program (NGSP) for reliable HbA1c testing accuracy.\"]', '[\"\\u2022 Thyroid function: T3, T4, TSH, FT3, FT4\",\"\\u2022 Hormones: \\u03b2\\u2011HCG, LH, FSH, PRL, Testosterone (Tes), Progesterone (Prog), AMH, Cortisol\",\"\\u2022 Cardiac markers: cTnI, cTnT, Myoglobin (Myo), CK\\u2011MB, D\\u2011Dimer, NT\\u2011proBNP, sST2\",\"\\u2022 Inflammation: HsCRP\\/CRP, PCT, SAA, IL\\u20116\",\"\\u2022 Renal\\/urine: NGAL, Urine microalbumin (MAU)\",\"\\u2022 Digestive\\/others: G17 (gastrin\\u201117), PGI\\/PGII (pepsinogens), FOB, Calprotein\",\"\\u2022 Tumor markers: Ferritin, PSA, CEA, AFP, CA125, CA153, CA199, Free PSA (FPSA)\",\"\\u2022 Allergy: IgE\",\"\\u2022 Infectious disease: HCV antibody, HBsAg, HIV\",\"\\u2022 COVID\\u201119: COVID19 neutralizing Ab, COVID19 antigen\",\"\\u2022 Metabolic\\/others: HbA1c, 25\\u2011OH\\u2011VD (vitamin D)\"]', '[\"products\\/Yh0V4V4KGr3J3E23DpMc40S5toAKCR9y7rFgjr2D.jpg\"]', 'products/Yh0V4V4KGr3J3E23DpMc40S5toAKCR9y7rFgjr2D.jpg', 0, NULL, '2026-02-11 14:25:37', '2026-02-11 14:25:37', NULL),
(19, 'Lansion Bio LS‑1100', 'immunology', 'The Lansion Bio LS‑1100 is a portable fluorescence immunoassay analyzer that uses Time‑resolved Fluorescence Immunoassay (TRFIA) technology for fast, quantitative detection of multiple biomarkers. It supports various sample types (serum, plasma, whole blood, nasal swab/urine) and is used in clinical labs, emergency, ICU, and POC settings.', '[\"\\u2022 Method: Time\\u2011resolved Fluorescence Immunoassay (TRFIA)\",\"\\u2022 Sample types: Serum, plasma, whole blood, nasal swab\",\"\\u2022 Weight: ~1.3\\u202fkg\",\"\\u2022 Dimensions: 225 \\u00d7 152 \\u00d7 105\\u202fmm (L\\u00d7W\\u00d7H)\",\"\\u2022 Display: 7\\u2033 touchscreen\",\"\\u2022 Data storage: ~10,000 results\",\"\\u2022 Printer: Built\\u2011in thermal printer\",\"\\u2022 Battery: Built\\u2011in lithium battery (standby use ~10\\u202fh)\",\"\\u2022 Communication: RS232 (LIS\\/HIS), USB (some listings indicate WIFI & Bluetooth)\",\"\\u2022 Operation: Portable, intuitive TRFIA workflow\"]', '[\"\\u2022 TRFIA technology for ultra\\u2011sensitive quantitative immunoassay results (Time\\u2011Resolved Fluorescence Immunoassay)\",\"\\u2022 Portable and lightweight design (\\u22481.3\\u202fkg)\",\"\\u2022 7\\u2033 touchscreen with intuitive operation and display\",\"\\u2022 Built\\u2011in thermal printer for immediate result printing\",\"\\u2022 Large data storage (\\u224810,000 results)\",\"\\u2022 Built\\u2011in lithium battery for extended use (\\u224810\\u202fh standby)\",\"\\u2022 Multiple connectivity options (RS232\\/LIS\\/HIS, USB, Wi\\u2011Fi, Bluetooth)\",\"\\u2022 Works with various sample types: serum, plasma, whole blood (and some kits urine)\",\"\\u2022 Quick, quantitative results ideal for clinical settings (labs, ER, ICU, POC)\"]', '[\"\\u2022 Diabetes monitoring: HbA1c, blood glucose\\u2011related markers\",\"\\u2022 Cardiac markers: cTnI, CK\\u2011MB, Myoglobin, NT\\u2011proBNP, BNP, D\\u2011Dimer, ST2\",\"\\u2022 Inflammation & infection: CRP\\/hs\\u2011CRP, PCT, IL\\u20116, SAA, HCY, SARS\\u2011CoV\\u20112, Monkeypox antibody\",\"\\u2022 Hormones & thyroid: TSH, TT3, TT4, FT3, FT4, LH, FSH, PRL, Progesterone, Testosterone, AMH\",\"\\u2022 Tumor markers: PSA, fPSA, CEA, AFP, CA125, CA153, CA199\",\"\\u2022 Gastric & renal markers: PGI\\/PGII, G17, NGAL, microalbumin\",\"\\u2022 Bone & metabolism: 25\\u2011OH\\u2011Vitamin D, Ferritin, B12\",\"\\u2022 Immune & allergy markers: IgE, IgG4, RF, CCP, ASO\",\"\\u2022 Clinical settings: Hospitals, emergency rooms, ICU, outpatient clinics, mobile\\/POC testing\"]', '[]', '[\"\\u2022 CE Mark (IVD) \\u2014 certified for in\\u2011vitro diagnostic use under European standards.\",\"\\u2022 ISO 13485 \\u2014 manufacturer quality management system certification (medical device).\",\"\\u2022 EU IVDR Listing (2017\\/746) \\u2014 LS\\u20111100 is registered under the European In\\u2011Vitro Diagnostic Regulation.\"]', '[\"\\u2022 HbA1c Test Kit (diabetes monitoring)\",\"\\u2022 CRP Test Kit (inflammation)\",\"\\u2022 hs\\u2011CRP Test Kit (high\\u2011sensitivity CRP)\",\"\\u2022 PCT Test Kit (procalcitonin)\",\"\\u2022 SAA & SAA\\/CRP Test Kits (serum amyloid A\\/inflammation)\",\"\\u2022 Cardiac Marker Kits:\",\"\\u2013 BNP, cTnI, CK\\u2011MB, Myoglobin, D\\u2011Dimer, H\\u2011FABP, NT\\u2011proBNP, FDP\",\"\\u2022 Hormone Kits: \\u03b2\\u2011HCG, LH, FSH, PRL, AMH, Progesterone, E2, Testosterone\",\"\\u2022 Thyroid Kits: TT3, TT4, FT3, FT4, TSH\",\"\\u2022 Bone Metabolism \\/ Gastric \\/ Renal Kits: 25\\u2011OH\\u2011VD, PGI\\/PGII, G\\u201117, mAlB, NGAL\",\"\\u2022 Anemia \\/ Tumor Kits: Ferritin, B12, PSA, fPSA\",\"\\u2022 Immune \\/ Nervous System Kits: IgE, IgG4, RF, CCP, ASO, A\\u03b21\\u201142, P\\u2011tau\\u2011181, AD7c\\u2011NTP\",\"\\u2022 COVID\\u201119 Related Kits: (COVID\\u201119) IgM\\/IgG, COVID\\u201119 Antigen, SARS\\u2011CoV\\u20112 Neutralizing Antibody\"]', '[\"products\\/CO8fx9fM0HfONO1P63PiDzyqKC50efq4pdW0pDPr.jpg\"]', 'products/CO8fx9fM0HfONO1P63PiDzyqKC50efq4pdW0pDPr.jpg', 0, NULL, '2026-02-11 15:29:25', '2026-02-11 15:29:25', NULL);
INSERT INTO `products` (`id`, `name`, `category`, `overview`, `specifications`, `features`, `applications`, `technical_specs`, `certifications`, `reagent_lists`, `images`, `featured_image`, `sort_order`, `brochure`, `created_at`, `updated_at`, `deleted_at`) VALUES
(20, '(COYOTE) MINI8 PLUS', 'molecular', 'The COYOTE FlashDetect™ Mini8 Plus is a compact, portable real‑time qPCR molecular diagnostic system designed for on‑site PCR testing. It enables rapid, calibration‑free real‑time PCR detection with intuitive software, universal consumable compatibility, and easy setup — ideal for decentralized testing, clinical settings, field use, and mobile labs. The Mini8 Plus is registered as a Class III medical device and included in the World Health Organization’s recommended equipment list.', '[\"\\u2022 Throughput: 8 samples (8\\u202f\\u00d7\\u202f0.2\\u202fmL PCR tubes)\",\"\\u2022 Reaction volume: 10\\u202f\\u2013\\u202f200\\u202f\\u00b5L\",\"\\u2022 Detection channels: Dual \\u2014 SYBR\\/FAM + ROX\\/Texas Red or SYBR\\/FAM + HEX\\/VIC\",\"\\u2022 Temperature range: 4\\u202f\\u00b0C\\u202f\\u2013\\u202f100\\u202f\\u00b0C\",\"\\u2022 Heating\\/cooling rate: \\u2265\\u202f1.5\\u202f\\u00b0C\\/s\",\"\\u2022 Temperature control accuracy: \\u2264\\u202f0.5\\u202f\\u00b0C\",\"\\u2022 Temperature uniformity: \\u2264\\u202f1\\u202f\\u00b0C\",\"\\u2022 Dimensions (L\\u00d7W\\u00d7H): 205\\u202f\\u00d7\\u202f190\\u202f\\u00d7\\u202f98\\u202fmm\",\"\\u2022 Net weight: ~2.1\\u202fkg\",\"\\u2022 Power supply: 12\\u202fV DC, 10\\u202fA\",\"\\u2022 Software: Windows\\u2011based operation\",\"\\u2022 Consumables: Standard 0.2\\u202fmL PCR tubes with flat caps\",\"\\u2022 Sensitivity: Can detect as low as ~1 copy of target nucleic acid (high sensitivity)\"]', '[\"\\u2022 Compact & portable \\u2014 light (~2.1\\u202fkg) and small footprint for on\\u2011site use\",\"\\u2022 Intuitive software \\u2014 program setup in ~30\\u202fseconds with minimal training\",\"\\u2022 Calibration\\u2011free after moving \\u2014 no need to recalibrate when relocated\",\"\\u2022 Open system \\u2014 compatible with universal PCR consumables\",\"\\u2022 Dual detection channels (SYBR\\/FAM + ROX\\/Texas Red or SYBR\\/FAM + HEX\\/VIC)\",\"\\u2022 Quick results \\u2014 rapid real\\u2011time qPCR operation (fast cycling)\",\"\\u2022 12\\u202fV DC power support for field\\/portable deployment\",\"\\u2022 WHO recommended & Class III medical device recognition\"]', '[\"COYOTE Mini8 Plus \\u2013 Applications\",\"\\u2022 Molecular diagnostics: Rapid detection of viral, bacterial, and fungal pathogens\",\"\\u2022 Infectious diseases: SARS\\u2011CoV\\u20112, Influenza A\\/B, HIV, Hepatitis, Monkeypox, and other viral\\/bacterial targets\",\"\\u2022 Genetic testing & research: Gene expression, SNP analysis, pathogen genotyping\",\"\\u2022 Point\\u2011of\\u2011care testing (POCT): Hospitals, clinics, field\\/mobile labs, quarantine checkpoints\",\"\\u2022 Food safety & veterinary testing: Pathogen screening and animal health monitoring\",\"\\u2022 Environmental & academic research: Microbial detection in environmental samples\"]', '[\"\\u2022 Sample throughput: 8 \\u00d7 0.2\\u202fmL PCR tubes\",\"\\u2022 Reaction volume: 10\\u202f\\u2013\\u202f200\\u202f\\u00b5L\",\"\\u2022 Detection channels: Dual \\u2014 SYBR\\/FAM + ROX\\/Texas Red or SYBR\\/FAM + HEX\\/VIC\",\"\\u2022 Temperature range: 4\\u202f\\u2013\\u202f100\\u202f\\u00b0C\",\"\\u2022 Heating\\/cooling rate: \\u2265 1.5\\u202f\\u00b0C\\/s\",\"\\u2022 Temperature accuracy: \\u2264 \\u00b10.5\\u202f\\u00b0C\",\"\\u2022 Temperature uniformity: \\u2264 \\u00b11\\u202f\\u00b0C\",\"\\u2022 Dimensions: 205 \\u00d7 190 \\u00d7 98\\u202fmm (L\\u00d7W\\u00d7H)\",\"\\u2022 Weight: ~2.1\\u202fkg\",\"\\u2022 Power: 12\\u202fV DC, 10\\u202fA\",\"\\u2022 Software: Windows\\u2011based control & data analysis\",\"\\u2022 Consumables: Standard 0.2\\u202fmL PCR tubes with flat caps\"]', '[\"COYOTE Mini8 Plus \\u2013 Certifications\",\"\\u2022 Class\\u202fIII Medical Device registration \\u2014 Mini8\\u202fPlus is officially registered as a Class\\u202fIII medical device.\",\"\\u2022 World Health Organization (WHO) recommendation \\u2014 selected into WHO\\u2019s recommended equipment list for molecular diagnostics.\",\"\\u2022 CE Mark \\u2014 the platform holds CE certification for IVD equipment.\"]', '[\"\\u2022 DirectDetect\\u2122 SARS\\u2011CoV\\u20112 Detection Kit \\u2013 real\\u2011time PCR for SARS\\u2011CoV\\u20112 (ORF1ab & N gene) compatible with Mini8\\u202fPlus and other PCR systems (24\\/48\\/96 tests per kit).\",\"\\u2022 FlashDetect\\u2122 Respiratory Syncytial Virus & Mycoplasma Pneumoniae Kit \\u2013 detects RSV & MP by real\\u2011time PCR.\",\"\\u2022 FlashDetect\\u2122 Influenza A & Influenza B Virus Kit \\u2013 real\\u2011time PCR for flu A and B.\",\"\\u2022 FlashDetect\\u2122 SARS\\u2011CoV\\u20112 & Flu A & Flu B & RSV Kit \\u2013 all\\u2011in\\u2011one cartridge for 4 respiratory targets (SARS\\u2011CoV\\u20112, Influenza A, Flu B, RSV).\",\"\\u2022 STI panels (e.g., MG\\/TV\\/MH, CT\\/NG\\/UU, HSV\\u20111\\/HSV\\u20112) \\u2013 real\\u2011time PCR assays for sexually transmitted infections (may be available RUO).\",\"\\u2022 MRSA\\/SA Assay \\u2013 PCR for methicillin\\u2011resistant and sensitive Staphylococcus aureus.\",\"\\u2022 Monkeypox Virus Assay \\u2013 rapid PCR test for Mpox virus.\",\"\\u2022 NG\\/UU (Neisseria gonorrhoeae & Ureaplasma urealyticum) Kits \\u2013 PCR assays for STIs.\"]', '[\"products\\/uTDY0YwzmbGhmY1ruL25OUGgP7a6z9kC7dZPmwuj.png\"]', 'products/uTDY0YwzmbGhmY1ruL25OUGgP7a6z9kC7dZPmwuj.png', 0, NULL, '2026-02-11 16:35:04', '2026-02-11 16:35:04', NULL),
(21, 'GEN DX GENEYE (HPV )', 'molecular', 'GEN DX HPV refers to a diagnostic PCR test for Human Papillomavirus (HPV) that detects and/or genotypes HPV DNA — especially high‑risk types linked to cancer (such as HPV 16, 18, and others). These assays are used in laboratories to screen, diagnose, or genotype HPV infections using real‑time or conventional PCR methods.', '[\"\\u2022 Method: Real\\u2011time PCR (multiplex)\",\"\\u2022 Targets: High\\u2011risk HPV types (16, 18, 31, 33\\u2026) \\u00b1 low-risk (6, 11)\",\"\\u2022 Sample: Cervical\\/vaginal swabs, liquid cytology\",\"\\u2022 Sensitivity: ~400\\u2013500 copies\\/mL\",\"\\u2022 Detection: Fluorescent probes (FAM, VIC\\/HEX, ROX, Cy5)\",\"\\u2022 Kit size: 24\\u201396 reactions\",\"\\u2022 Run time: ~60\\u201390 min\",\"\\u2022 Controls: Internal, positive & negative\",\"\\u2022 Compatibility: Standard real\\u2011time PCR instruments\",\"\\u2022 Storage: \\u201320\\u202f\\u00b0C, shelf life ~12 months\",\"\\u2022 Use: HPV DNA detection & genotyping for screening\\/diagnosis\"]', '[\"\\u2022 Multiplex real\\u2011time PCR detection for multiple HPV genotypes (high\\u2011risk and sometimes low\\u2011risk)\",\"\\u2022 High sensitivity & specificity with probe\\u2011based chemistry (e.g., TaqMan)\",\"\\u2022 Simultaneous genotyping of common high\\u2011risk types (such as 16, 18, 31, 33, etc.)\",\"\\u2022 Internal controls included to validate extraction and PCR performance\",\"\\u2022 Compatible with major real\\u2011time PCR instruments (FAM\\/VIC\\/HEX\\/ROX channels)\",\"\\u2022 Fast turnaround \\u2014 results typically in ~1\\u20131.5\\u202fhours\",\"\\u2022 Prevents contamination (often includes UDG systems or control enzymes)\",\"\\u2022 Qualitative\\/quantitative output depending on kit design\"]', '[\"\\u2022 Cervical cancer screening: Detects high\\u2011risk HPV DNA in women\",\"\\u2022 HPV genotyping: Identifies specific high\\u2011risk (16, 18, 31, 33\\u2026) and sometimes low\\u2011risk (6, 11) types\",\"\\u2022 Clinical diagnostics: Triage after abnormal cytology\",\"\\u2022 Epidemiology & research: Population HPV prevalence studies\",\"\\u2022 Sample types: Cervical\\/vaginal swabs, liquid\\u2011based cytology specimens\"]', '[]', '[\"\\u2022 CE\\u2011IVD marked \\u2014 approved for in\\u2011vitro diagnostic use in Europe (nanohelix.net\",\")\",\"\\u2022 ISO 13485 certified manufacturer \\u2014 quality management for medical devices (nanohelix.net\",\")\",\"\\u2022 FDA\\/CDC compliance (if applicable) \\u2014 meets US guidelines for molecular HPV testing (for some kits)\",\"\\u2022 WHO prequalification (some kits) \\u2014 recommended for HPV screening programs in low-resource settings\"]', '[]', '[\"products\\/qm3ZXdo6DuHpoeLVGcObha6iTQ6rTslw68P96V4u.jpg\"]', 'products/qm3ZXdo6DuHpoeLVGcObha6iTQ6rTslw68P96V4u.jpg', 0, NULL, '2026-02-11 16:40:02', '2026-02-11 16:40:15', NULL),
(22, 'CM250', 'chemistry', 'The CM250 is a compact benchtop clinical chemistry and immunoturbidimetry analyzer from Wiener Lab, designed for routine blood chemistry testing in medical laboratories. It’s a random‑access, automatic analyzer that handles multiple analytes and supports STAT samples, profiles, and quality control workflows.', '[\"Type: Automatic clinical chemistry & immunoturbidimetry analyzer (benchtop, random access)\",\"\\u2022 Throughput: Up to 230 tests\\/hour\",\"\\u2022 Sample positions: 48 (primary tubes or sample cups, continuous load)\",\"\\u2022 Sample volume: 2\\u2013100\\u202f\\u00b5L\",\"\\u2022 Reagent positions: 48 (Peltier\\u2011cooled)\",\"\\u2022 Reaction tray: 80 washable cuvettes with 0.6\\u202fcm light path\",\"\\u2022 Optical system: Double beam photometer with multiple interference filters (340\\u2013750\\u202fnm)\",\"\\u2022 Analytical modes: Endpoint, kinetics (1 & 2 point), immunoturbidimetry, calibration curves, routine profiles\",\"\\u2022 Quality control: Levey\\u2011Jennings & Westgard rules\",\"\\u2022 Barcode reader: Optional built\\u2011in\",\"\\u2022 Water consumption: <\\u202f1\\u202fL\\/hour\",\"\\u2022 Weight: ~59\\u202fkg\",\"\\u2022 Power: 85\\u2013240\\u202fVAC, 50\\/60\\u202fHz\"]', '[\"\\u2022 Fully automatic, random access clinical chemistry analyzer for routine, STAT, and profile testing.\",\"\\u2022 Up to 230 tests\\/hour throughput.\",\"\\u2022 48 sample positions with continuous loading; accepts primary tubes or sample cups.\",\"\\u2022 48 reagent positions with Peltier cooling for reagent stability.\",\"\\u2022 Built\\u2011in barcode reader for sample tracking.\",\"\\u2022 80 washable cuvettes with air incubation (30\\u202f\\u00b0C & 37\\u202f\\u00b0C).\",\"\\u2022 Double\\u2011beam optical system with multiple interference filters for versatility.\",\"\\u2022 Multiple analytical modes: endpoint, kinetics, immunoturbidimetry, calibration curves.\",\"\\u2022 Automatic sample dilution and pre\\u2011dilution for pathological samples.\",\"\\u2022 Quality control tools: Levey\\u2011Jennings charts and Westgard rules supported.\",\"\\u2022 PC\\/LIS connectivity and data handling with USB ports.\",\"\\u2022 Low water consumption (<\\u202f1\\u202fL\\/hr).\"]', '[\"\\u2022 Clinical chemistry testing: glucose, urea, creatinine, liver and kidney function markers\",\"\\u2022 Immunoturbidimetry assays: CRP, rheumatoid factor, complement, proteins\",\"\\u2022 Routine labs: hospitals, clinics, outpatient labs\",\"\\u2022 STAT testing: rapid processing of emergency samples\",\"\\u2022 Profiles and panels: automated multiple analyte testing for comprehensive metabolic panels\"]', '[]', '[\"\\u2022 CE\\u2011IVD marked \\u2014 approved for in\\u2011vitro diagnostic use in Europe\",\"\\u2022 ISO 13485 certified manufacturer \\u2014 quality management system for medical devices\",\"\\u2022 ISO 9001 \\u2014 general quality management standard for manufacturing processes\",\"\\u2022 Local approvals \\u2014 country-specific regulatory approvals may apply depending on distribution\"]', '[\"Glucose\",\"Urea\\/Blood Urea Nitrogen (BUN)\",\"Creatinine\",\"Uric Acid\",\"Total Bilirubin\",\"Direct Bilirubin\",\"AST (GOT)\",\"ALT (GPT)\",\"Alkaline Phosphatase (ALP)\",\"Gamma GT (GGT)\",\"Total Protein\",\"Albumin\",\"Globulin (calculated)\",\"Albumin\\/Globulin ratio\",\"Total Cholesterol\",\"HDL-Cholesterol\",\"LDL-Cholesterol (calculated)\",\"Triglycerides\",\"VLDL (calculated)\",\"Calcium\",\"Phosphorus\",\"Magnesium\",\"Sodium\",\"Potassium\",\"Chloride\",\"Iron \\/ TIBC \\/ Transferrin\",\"Bilirubin (total & direct)\",\"ALT \\/ AST \\/ ALP \\/ GGT\",\"Albumin \\/ Total Protein\",\"Urea \\/ Creatinine \\/ Uric Acid\",\"Amylase\",\"Lipase\",\"Total Cholesterol \\/ HDL \\/ LDL \\/ VLDL\",\"Triglycerides\",\"Lipoprotein(a) (if available)\",\"Apolipoprotein A1 \\/ B\",\"ALT \\/ AST \\/ ALP \\/ GGT\",\"LDH (Lactate Dehydrogenase)\",\"CK \\/ CK-MB (if chem test supported)\",\"Amylase \\/ Lipase\",\"C-Reactive Protein (CRP)\",\"Rheumatoid Factor (RF)\",\"Complement C3 \\/ C4\",\"Immunoglobulins (IgG, IgA, IgM)\",\"Ferritin\",\"Transferrin\",\"Sodium\",\"Potassium\",\"Chloride\",\"Calcium\",\"Phosphorus\",\"Magnesium\",\"Uric Acid\",\"Amylase \\/ Lipase\",\"LDH\",\"Bicarbonate \\/ CO\\u2082 (if module installed)\",\"Calibrators \\u2014 multi-level for each assay\",\"Controls \\u2014 normal, low, high levels\",\"Wash solutions \\u2014 for cuvette cleaning\",\"Deionized\\/distilled water \\u2014 for reagent preparation and washing\",\"Reaction cuvettes \\u2014 80 reusable cuvettes\"]', '[\"products\\/bjacp05gTzIhNTq6cGVBKpjSQc0RRKEfMnhDYvBz.jpg\"]', 'products/bjacp05gTzIhNTq6cGVBKpjSQc0RRKEfMnhDYvBz.jpg', 0, NULL, '2026-02-11 17:01:05', '2026-02-11 17:01:05', NULL),
(23, 'CM260', 'chemistry', 'The Wiener Lab CM260 is a fully automatic benchtop clinical chemistry and immunoturbidimetry analyzer designed for medium-throughput laboratories. It delivers up to 250 tests/hour, supports random access, and features barcode-based sample/reagent management, automatic dilution, and comprehensive QC tools. Ideal for routine, STAT, and profile testing in hospitals and diagnostic labs.', '[\"\\u2022 Type: Fully automatic benchtop clinical chemistry & immunoturbidimetry analyzer with barcode reader\",\"\\u2022 Throughput: Up to 250 tests\\/hour\",\"\\u2022 Sample positions: 48 positions (continuous load)\",\"\\u2022 Sample volume: 2\\u2013100 \\u00b5L\",\"\\u2022 Reagent positions: 48 positions (continuous load with barcode)\",\"\\u2022 Water consumption: < 1 L\\/hour\",\"\\u2022 Reaction tray: 80 cuvettes, 0.6 cm light path (air incubation at 30 \\u00b0C & 37 \\u00b0C)\",\"\\u2022 Optical system: Double-beam photometer with multiple interference filters (340\\u2013767 nm; optional 380\\/450 nm), range \\u20130.1\\u20133.5 Abs\",\"\\u2022 Measurement modes: Endpoint, 1-pt\\/2-pt kinetics, turbidimetry, factor\\/standard\\/curve calibration; routine, STAT, profiles\",\"\\u2022 Automatic dilution: For pathological samples and substrate limitations\",\"\\u2022 Quality control: Levey\\u2013Jennings charts & Westgard rules\",\"\\u2022 Communication: LIS\\/Host Query automatic connection\",\"\\u2022 Dimensions: ~80 cm (W) \\u00d7 48 cm (H) \\u00d7 57 cm (D)\",\"\\u2022 Weight: ~57 kg\"]', '[\"\\u2022 Fully automatic benchtop clinical chemistry & immunoturbidimetry analyzer\",\"\\u2022 Up to 250 tests\\/hour throughput\",\"\\u2022 Random access and continuous loading of samples and reagents\",\"\\u2022 48 sample + 48 reagent positions with barcode tracking\",\"\\u2022 80 washable cuvettes with air incubation (30 \\u00b0C & 37 \\u00b0C)\",\"\\u2022 Double-beam photometer with multi-wavelength filters\",\"\\u2022 Multiple analytical modes: endpoint, kinetics, turbidimetry, calibration curves\",\"\\u2022 Automatic sample dilution for high-concentration samples\",\"\\u2022 Quality control tools: Levey-Jennings & Westgard rules\",\"\\u2022 LIS\\/Host connectivity for seamless lab data integration\"]', '[\"\\u2022 Routine clinical chemistry testing (metabolic panels, liver\\/kidney function)\",\"\\u2022 Immunoturbidimetry assays (e.g., CRP, RF, proteins)\",\"\\u2022 STAT and emergency testing\",\"\\u2022 Profiles and panels (comprehensive chemistry + specialized assays)\",\"\\u2022 Hospitals, diagnostic labs, outpatient labs, and reference laboratories\"]', '[]', '[\"\\u2022 CE-IVD Mark \\u2014 certified for in-vitro diagnostic use in Europe and other CE markets.\",\"\\u2022 ISO 13485 Certified Manufacturer \\u2014 quality management system for medical device production.\",\"\\u2022 ISO 9001 Quality Management \\u2014 general quality system standard applied at the manufacturer level.\"]', '[\"Albumin\",\"Alkaline Phosphatase (ALP)\",\"AST (GOT)\",\"ALT (GPT)\",\"\\u03b3-GT\",\"Total Bilirubin\",\"Direct Bilirubin\",\"Total Protein\",\"Creatinine\",\"Urea (BUN)\",\"Uric Acid\",\"Glucose\",\"Calcium\",\"Phosphorus\",\"Magnesium\",\"Iron\",\"Homocysteine\",\"Sodium\",\"Potassium\",\"Chloride\",\"C-Reactive Protein (CRP)\",\"Immunoglobulin A (IgA)\",\"Immunoglobulin G (IgG)\",\"Immunoglobulin M (IgM)\",\"Immunoglobulin E (IgE)\",\"Complement C3\",\"Complement C4\",\"Transferrin\",\"Ferritin\",\"Microalbumin\",\"\\u03b1-1-acid glycoprotein (AGP)\",\"UIBC\\/TIBC\",\"Carbon Dioxide (CO\\u2082)\",\"Ammonium\",\"Phosphorus inorganic (PO\\u2083\\/PHOS)\",\"Creatine Kinase MB (CK-MB)\",\"LDH\",\"Rheumatoid Factor (RF)\",\"D-Dimer\",\"Antistreptolysin O (ASO)\",\"Fructosamine\",\"Lipid panel: Total Cholesterol, HDL Cholesterol, LDL Cholesterol, Triglycerides\",\"HbA1c (diabetes marker)\",\"Amylase\",\"Lipase\"]', '[\"products\\/T8gjQdxeRRkvrc1Wn2kfXAxZBLIIfXMyrdUaf40I.jpg\"]', 'products/T8gjQdxeRRkvrc1Wn2kfXAxZBLIIfXMyrdUaf40I.jpg', 0, NULL, '2026-02-12 15:12:08', '2026-02-12 15:12:08', NULL),
(24, 'H8', 'chemistry', 'The H8 Hematology Analyzer is a fully automated 5-part differential system designed for high-throughput clinical laboratories. It provides rapid and accurate CBC + 5-part WBC differential, supporting routine and STAT testing with advanced data management and quality control features.', '[\"\\u2022 Method: High-Performance Liquid Chromatography (HPLC) \\u2014 gold-standard for HbA1c testing.\",\"\\u2022 Test modes: Standard (HbA1c), Variant Mode, Thalassemia Mode (HbF, HbA2, HbE\\/D\\/S\\/C).\",\"\\u2022 Measurement range: ~3 %\\u201318 % HbA1c.\",\"\\u2022 Precision: CV \\u2264 1.5 %.\",\"\\u2022 Test speed: ~130 sec per sample (Variant Mode); ~380 sec per sample (Thalassemia Mode).\",\"\\u2022 Sample types: Venous whole blood, finger\\/prick peripheral blood, lyophilized whole blood.\",\"\\u2022 Sample loader: 10 positions (continuous loading).\",\"\\u2022 Photometer: Dual detectors (\\u2248415 nm + 500 nm) for improved signal quality.\",\"\\u2022 Display: 10.1\\u2033 TFT touch LCD.\",\"\\u2022 Software: Linux-based with self-diagnosis.\",\"\\u2022 Reagent kits: Eluent A, Eluent B, Eluent C, Hemolysin, Calibrator, QC materials.\",\"\\u2022 Data storage: ~4000 results.\",\"\\u2022 Connections: USB \\/ LAN \\/ LIS compatible.\",\"\\u2022 Printer support: Built-in thermal + external printer.\",\"\\u2022 Operating conditions: ~10\\u201330 \\u00b0C, humidity \\u2264 80 %.\",\"\\u2022 Power: AC 100\\u2013240 V, 50\\/60 Hz.\",\"\\u2022 Size & weight: ~600 \\u00d7 360 \\u00d7 540 mm, ~49 kg\"]', '[\"\\u2022 5-part WBC differential with laser\\/flow cytometry technology\",\"\\u2022 High throughput (typically ~60\\u201390 samples\\/hour, model dependent)\",\"\\u2022 Comprehensive CBC parameters + histograms\\/scattergrams\",\"\\u2022 Auto sampler with continuous loading\",\"\\u2022 Large touchscreen interface\",\"\\u2022 Built-in QC & calibration programs\",\"\\u2022 LIS connectivity & barcode support\",\"\\u2022 Low reagent consumption\"]', '[\"\\u2022 Routine Complete Blood Count (CBC)\",\"\\u2022 5-part WBC differential\",\"\\u2022 Hospitals, diagnostic labs, reference labs\",\"\\u2022 STAT\\/emergency hematology testing\"]', '[]', '[\"\\u2022 NGSP certified \\u2014 standardized by the National Glycohemoglobin Standardization Program for accurate HbA1c results.\",\"\\u2022 IFCC certified \\u2014 in accordance with International Federation of Clinical Chemistry reference methods.\",\"\\u2022 CE\\u2011IVD Mark \\u2014 meets European in\\u2011vitro diagnostic device regulatory requirements (as noted in product listings).\",\"\\u2022 ISO\\u202f13485 quality management for the manufacturer (product marketed under this quality system).\"]', '[\"\\u2022 Eluent A \\u2013 buffer solution for early protein elution\",\"\\u2022 Eluent B \\u2013 buffer for intermediate protein elution\",\"\\u2022 Eluent C \\u2013 buffer for final protein elution\",\"\\u2022 Hemolytic agent (Hemolysin) \\u2013 to lyse red blood cells and release glycated hemoglobin\",\"\\u2022 Calibrator \\u2013 for instrument calibration and standardization\",\"\\u2022 Quality Control (QC) materials \\u2013 control samples for assay QC monitoring\",\"\\u2022 Chromatography column \\u2013 ion\\u2011exchange column used for HPLC separation\",\"\\u2022 Filters \\u2013 replaceable filters specific to H8 for fluid\\/particle control\"]', '[\"products\\/AwRY08tO2VdHmehw9YdJWjPeFqzN7Gr4soRTVcp6.jpg\"]', 'products/AwRY08tO2VdHmehw9YdJWjPeFqzN7Gr4soRTVcp6.jpg', 0, NULL, '2026-02-12 15:15:43', '2026-02-12 15:15:53', NULL),
(25, 'H100', 'chemistry', 'The Lifotronic H100 is a fully automated hemoglobin analyzer that uses High‑Performance Liquid Chromatography (HPLC) — the gold standard method for measuring glycated hemoglobin (HbA1c) and identifying hemoglobin variants (e.g., β‑thalassemia, HbE, HbS). It delivers rapid, accurate results for diabetes monitoring and hemoglobinopathy detection in clinical labs.', '[\"\\u2022 Methodology: High\\u2011Performance Liquid Chromatography (HPLC) \\u2014 gold standard for HbA1c detection.\",\"\\u2022 Test modes: Variant Mode & \\u03b2\\u2011Thalassemia Mode (one\\u2011click switch).\",\"\\u2022 Test speed: Variant Mode: ~96\\u202fsec per test; Thalassemia Mode: ~350\\u202fsec per test.\",\"\\u2022 Sample loader: 50 positions (expandable to 110 positions) + 1 STAT position.\",\"\\u2022 Sample volume: ~5\\u202f\\u00b5L whole blood.\",\"\\u2022 Display: 10.1\\u2033 TFT true color LCD touchscreen.\",\"\\u2022 Data storage: Up to 20,000 samples.\",\"\\u2022 Precision: CV <\\u202f1.0\\u202f% (HbA1c).\",\"\\u2022 Connection: RS232, USB, LIS compatible.\",\"\\u2022 Barcode support: Internal or handheld barcode scanner available.\",\"\\u2022 Printer: Built\\u2011in thermal printer + external printer support.\",\"\\u2022 Operating temperature: ~10\\u202f\\u00b0C\\u202f\\u2013\\u202f30\\u202f\\u00b0C; humidity \\u2264\\u202f80\\u202f%.\",\"\\u2022 Storage temperature: ~0\\u202f\\u00b0C\\u202f\\u2013\\u202f55\\u202f\\u00b0C; storage humidity \\u2264\\u202f93\\u202f%.\",\"\\u2022 Dimensions: ~722\\u202f\\u00d7\\u202f532\\u202f\\u00d7\\u202f729\\u202fmm (L\\u00d7W\\u00d7H).\",\"\\u2022 Weight: ~55\\u201360.5\\u202fkg\"]', '[\"\\u2022 HPLC gold\\u2011standard method for HbA1c and hemoglobin variant analysis\",\"\\u2022 Fast throughput: ~96\\u202fsec for Variant Mode, ~350\\u202fsec for Thalassemia Mode\",\"\\u2022 Large sample capacity: up to 50 (expandable to 110) with STAT position\",\"\\u2022 Low sample volume: ~5\\u202f\\u00b5L whole blood\",\"\\u2022 Large touchscreen: 10.1\\u2033 true\\u2011color display with intuitive UI\",\"\\u2022 Built\\u2011in thermal printer + external printer support\",\"\\u2022 Barcode support (internal\\/handheld) for sample tracking\",\"\\u2022 Extensive data storage: up to 20,000 results\",\"\\u2022 High precision: CV <\\u202f1.0\\u202f% for HbA1c\",\"\\u2022 LIS\\/USB\\/RS232 connectivity for lab data integration\",\"\\u2022 Variant & Thalassemia modes for comprehensive hemoglobinopathy screening\",\"\\u2022 Automated workflow: sample handling, injection, and analysis\"]', '[\"\\u2022 Diabetes monitoring: Accurate measurement of HbA1c for long\\u2011term glycemic control in diabetic patients.\",\"\\u2022 Hemoglobin variant detection: Identifies and analyzes hemoglobin variants such as those seen in thalassemia or hemoglobinopathies.\",\"\\u2022 \\u03b2\\u2011Thalassemia screening and analysis: One\\u2011button mode for thalassemia assessment alongside routine HbA1c.\",\"\\u2022 Clinical laboratory use: Hospitals, diagnostic labs, diabetes clinics, and reference labs requiring high\\u2011accuracy HbA1c and variant analysis\"]', '[\"\\u2022 Methodology: High\\u2011Performance Liquid Chromatography (HPLC) \\u2014 gold\\u2011standard for HbA1c detection.\",\"\\u2022 Test Modes: Variant Mode & \\u03b2\\u2011Thalassemia Mode (one\\u2011click switch).\",\"\\u2022 Test Speed: ~96\\u202fsec\\/test (Variant Mode); ~350\\u202fsec\\/test (Thalassemia Mode).\",\"\\u2022 Sample Volume: ~5\\u202f\\u00b5L whole blood.\",\"\\u2022 Sample Loader: 50 or 110 positions + 1 STAT position.\",\"\\u2022 Display: 10.1\\u2033 TFT true\\u2011color LCD touchscreen.\",\"\\u2022 Data Storage: Up to 20,000 results.\",\"\\u2022 Connections: RS232, USB, LIS compatible.\",\"\\u2022 Barcode Support: Internal or handheld scanner.\",\"\\u2022 Printer: Built\\u2011in thermal + external printer support.\",\"\\u2022 Operating Temp: ~10\\u201330\\u202f\\u00b0C; Humidity: \\u2264\\u202f80\\u202f%.\",\"\\u2022 Storage Temp: ~0\\u201355\\u202f\\u00b0C; Humidity \\u2264\\u202f93\\u202f%.\",\"\\u2022 Dimensions: ~722\\u202f\\u00d7\\u202f532\\u202f\\u00d7\\u202f729\\u202fmm.\",\"\\u2022 Weight: ~55\\u201360.5\\u202fkg.\"]', '[\"\\u2022 NGSP certified \\u2014 standardized according to the National Glycohemoglobin Standardization Program for accurate HbA1c measurement.\",\"\\u2022 IFCC certified \\u2014 meeting International Federation of Clinical Chemistry traceability standards for HbA1c testing.\"]', '[\"\\u2022 Eluent A \\u2013 buffer for early hemoglobin elution\",\"\\u2022 Eluent B \\u2013 buffer for intermediate elution\",\"\\u2022 Eluent C \\u2013 buffer for later hemoglobin components in Variant Mode\",\"\\u2022 Eluent D \\u2013 buffer used in \\u03b2\\u2011Thalassemia Mode\",\"\\u2022 Hemolytic Agent L \\u2013 lyses red blood cells to release hemoglobin for analysis\",\"\\u2022 Calibrator material \\u2013 2\\u2011level calibrators for instrument calibration (HbA1c scale)\",\"\\u2022 Quality Control (QC) materials \\u2013 control samples for performance verification\",\"\\u2022 Chromatography column \\u2013 HPLC separation column (replaceable consumable)\",\"\\u2022 Filters \\u2013 fluid filters in HPLC flow path (replaceable)\"]', '[\"products\\/VeaEwR8RKrmC8yb2JsTO4CMXrb2zLAFjsCKhNiF8.png\"]', 'products/VeaEwR8RKrmC8yb2JsTO4CMXrb2zLAFjsCKhNiF8.png', 0, NULL, '2026-02-12 15:21:43', '2026-02-12 15:21:43', NULL),
(26, 'GH-900', 'chemistry', 'The GH‑900Plus is a fully automated HbA1c analyzer using High‑Performance Liquid Chromatography (HPLC) — the gold standard method for measuring glycated hemoglobin for diabetes monitoring. It delivers fast, accurate results with variant hemoglobin recognition and minimal hands‑on operation, making it suitable for clinical labs and diabetes management settings', '[\"\\u2022 Methodology: High\\u2011Performance Liquid Chromatography (HPLC) \\u2013 gold\\u2011standard HbA1c detection\",\"\\u2022 Test Range: 3\\u202f%\\u202f\\u2013\\u202f18\\u202f% HbA1c\",\"\\u2022 Precision: CV \\u2264\\u202f1.5\\u202f%\",\"\\u2022 Test Time: ~130\\u202fsec per test\",\"\\u2022 Sample Types: Venous blood, finger peripheral blood, lyophilized whole blood; ~10\\u202f\\u00b5L whole blood or ~400\\u202f\\u00b5L diluted blood\",\"\\u2022 Auto Sample Station: 5 positions\\/rack\",\"\\u2022 Photometer: Dual detector (415\\u202fnm + 500\\u202fnm)\",\"\\u2022 Filter: \\u2265\\u202f400T or \\u2265\\u202f800T (depending on config)\",\"\\u2022 Display: 10.1\\u2033 TFT true\\u2011color LCD touchscreen\",\"\\u2022 Software: Linux with self\\u2011diagnosis for system monitoring\",\"\\u2022 Reagent Kit: Eluent A, Eluent B, Hemolysin L, Calibrator; QC materials\",\"\\u2022 Data Storage: ~4000 sample results\",\"\\u2022 Connections: USB, LAN, LIS compatible\",\"\\u2022 Printer: Built\\u2011in thermal printer (external laser printer optional)\",\"\\u2022 Operating Conditions: 10\\u202f\\u2013\\u202f30\\u202f\\u00b0C; humidity \\u2264\\u202f80\\u202f%\",\"\\u2022 Power: AC 100\\u2011240\\u202fV, 50\\/60\\u202fHz, ~120\\u202fVA\",\"\\u2022 Dimensions: ~450\\u202f\\u00d7\\u202f360\\u202f\\u00d7\\u202f540\\u202fmm\",\"\\u2022 Weight: ~32.8\\u202fkg\"]', '[\"\\u2022 HPLC gold\\u2011standard technology for accurate HbA1c detection.\",\"\\u2022 Fast results: reports HbA1c in ~130\\u202fseconds per sample.\",\"\\u2022 High precision: CV\\u202f<\\u202f1.5\\u202f% for reliable measurements.\",\"\\u2022 Variant recognition: detects hemoglobin variants (HbF, V\\/S windows) for better clinical insight.\",\"\\u2022 Dual wavelength detection: reduces background interference for clearer signals.\",\"\\u2022 Degasser system: removes air bubbles to stabilize pressure and improve accuracy.\",\"\\u2022 Compact footprint: takes up minimal bench space.\",\"\\u2022 10.1\\u2033 touchscreen interface for intuitive operation.\",\"\\u2022 Data storage: holds ~4,000 results for trend review.\",\"\\u2022 Automated workflow: minimal hands\\u2011on handling and walk\\u2011away operation.\"]', '[\"\\u2022 Diabetes management: Accurate measurement of HbA1c for monitoring long\\u2011term glycemic control.\",\"\\u2022 Hemoglobinopathy screening: Detection of hemoglobin variants and abnormal peaks (helpful in thalassemia\\/hemoglobinopathy evaluation).\",\"\\u2022 Clinical laboratories: Routine HbA1c testing in hospitals, diagnostic labs, reference labs, and community health centers.\",\"\\u2022 Diabetes clinics: Onsite HbA1c monitoring for chronic disease management.\",\"\\u2022 Epidemiology & research: Population screening and data collection in diabetes studies\"]', '[]', '[\"\\u2022 NGSP Certified \\u2014 aligned with the National Glycohemoglobin Standardization Program for accurate clinical HbA1c reporting.\",\"\\u2022 IFCC Certified \\u2014 traceable to International Federation of Clinical Chemistry reference methods.\"]', '[\"\\u2022 Eluent A \\u2014 primary buffer for chromatographic separation\",\"\\u2022 Eluent B \\u2014 secondary buffer for intermediate elution\",\"\\u2022 Eluent C \\u2014 buffer for extended hemoglobin peaks (variant analysis)\",\"\\u2022 Eluent D \\u2014 buffer used in variant\\/\\u03b2\\u2011thalassemia modes\",\"\\u2022 Hemolytic Agent (Hemolysin L) \\u2014 lyses RBCs to release hemoglobin\",\"\\u2022 Calibrator Materials \\u2014 multi\\u2011level standards for instrument calibration\",\"\\u2022 Quality Control (QC) Materials \\u2014 control samples for QC monitoring\",\"\\u2022 Chromatography Column \\u2014 replaceable HPLC separation column\",\"\\u2022 System Filters \\u2014 fluid filters for HPLC flow path\",\"\\u2022 Waste & Solvent Bottles \\u2014 for eluents and system waste\"]', '[\"products\\/B07Uqc4wMv8IfICsyzPnlUw0N2OgyRmzGTXJx9XI.jpg\"]', 'products/B07Uqc4wMv8IfICsyzPnlUw0N2OgyRmzGTXJx9XI.jpg', 0, NULL, '2026-02-12 15:25:37', '2026-02-12 15:25:37', NULL),
(27, 'CBS-40', 'chemistry', 'The CBS‑40 is a benchtop automatic electrolyte analyzer that uses advanced Multi‑Biosensor Technology (MBT) to measure key clinical electrolytes — pH, potassium (K⁺), sodium (Na⁺), chloride (Cl⁻), and calcium (Ca²⁺) — quickly and accurately from plasma, serum, whole blood, urine, or other aqueous samples. It features a touchscreen interface, maintenance‑free sensors, simple reagent packs, and quick troubleshooting for efficient workflow in clinical labs, hospitals, and emergency settings', '[\"\\u2022 Method: Multi\\u2011Biosensor Technology (advanced maintenance\\u2011free biosensors)\",\"\\u2022 Sample size: ~60\\u2013120\\u202f\\u00b5L (blood, plasma, serum, urine)\",\"\\u2022 Throughput: ~120 tests\\/hour\",\"\\u2022 Measured parameters:\",\"Potassium (K\\u207a) \\u2014 0.50\\u202f\\u2013\\u202f20.00\\u202fmmol\\/L, CV <\\u202f1.0\\u202f%, res\\u202f0.01\",\"Sodium (Na\\u207a) \\u2014 15.0\\u202f\\u2013\\u202f200.0\\u202fmmol\\/L, ~1.0\\u202f% CV, res\\u202f0.1\",\"Chloride (Cl\\u207b) \\u2014 15.0\\u202f\\u2013\\u202f200.0\\u202fmmol\\/L, CV <\\u202f1.0\\u202f%, res\\u202f0.1\",\"Calcium (Ca\\u00b2\\u207a) \\u2014 0.10\\u202f\\u2013\\u202f6.00\\u202fmmol\\/L, ~1.5\\u202f% CV, res\\u202f0.01\",\"pH: 4.00\\u202f\\u2013\\u202f9.00, CV <\\u202f0.5\\u202f%, res\\u202f0.01\",\"\\u2022 Display: Color touchscreen (approx. 5.6\\u202fin)\",\"\\u2022 Printer: Built\\u2011in thermal printer\",\"\\u2022 Connectivity: RS232 + USB (with optional barcode scanner)\",\"\\u2022 Data storage: ~up to 6000 results (model dependent)\",\"\\u2022 Operating temp\\/humidity: ~0\\u201340\\u202f\\u00b0C \\/ \\u226485\\u202f% RH\",\"\\u2022 Power: AC ~80\\u2013260\\u202fV, 50\\u201160\\u202fHz, \\u226480\\u202fW\",\"\\u2022 Dimensions: ~21\\u202f\\u00d7\\u202f34\\u202f\\u00d7\\u202f40\\u202fcm\",\"\\u2022 Weight: ~6\\u202fkg\"]', '[\"\\u2022 Advanced multi\\u2011biosensor technology (MBT) for accurate electrolyte and pH measurement\",\"\\u2022 Measures: K\\u207a, Na\\u207a, Cl\\u207b, Ca\\u00b2\\u207a, and pH from blood\\/serum\\/plasma\\/urine\",\"\\u2022 Fast throughput: ~120 tests\\/hour\",\"\\u2022 Small sample volume required (\\u224860\\u2013120\\u202f\\u00b5L)\",\"\\u2022 Built\\u2011in color touchscreen for easy operation\",\"\\u2022 Built\\u2011in thermal printer for quick results printout\",\"\\u2022 Connectivity: RS232 + USB (barcode optional)\",\"\\u2022 Large onboard memory for patient results and QA data\",\"\\u2022 Compact, lightweight design for benchtop use\",\"\\u2022 Low maintenance with stable sensors and simple calibration\"]', '[\"\\u2022 Electrolyte balance assessment: measures sodium (Na\\u207a), potassium (K\\u207a), chloride (Cl\\u207b), calcium (Ca\\u00b2\\u207a) and pH levels in clinical samples to evaluate body fluid and electrolyte status.\",\"\\u2022 Clinical diagnosis & monitoring: used in hospital labs, emergency departments, intensive care units (ICU) and outpatient clinics to support diagnosis and management of conditions such as dehydration, renal dysfunction, acid\\u2011base imbalance, cardiac disorders, and metabolic disturbances.\",\"\\u2022 Point\\u2011of\\u2011care testing: suitable for rapid electrolyte assessments at the bedside or decentralized testing sites where quick turnaround is critical.\",\"\\u2022 Sample types: works with plasma, serum, urine or other biological fluids depending on configuration and reagent setups.\"]', '[]', '[\"\\u2022 CE\\u2011IVD Mark \\u2014 all B&E clinical analyzers (including the CBS series) are CE marked for in\\u2011vitro diagnostic use, indicating conformity with European regulatory requirements.\",\"\\u2022 ISO\\u202f13485 & ISO\\u202f9001 \\u2014 the manufacturer operates under ISO\\u202f13485 (medical device quality) and ISO\\u202f9001 certified systems.\"]', '[\"Electrolyte Reagent Pack (Closed Reagent Pack) \\u2014 contains all reagents for measuring sodium (Na\\u207a), potassium (K\\u207a), chloride (Cl\\u207b), calcium (Ca\\u00b2\\u207a), and pH in one replaceable pack.\",\"Multi\\u2011Level Calibrator Solution (Level 1) \\u2014 calibration standard for electrolyte measurement.\",\"Multi\\u2011Level Calibrator Solution (Level 2) \\u2014 secondary calibration standard.\",\"Quality Control Material \\u2013 Normal Level \\u2014 control solution to verify analyzer accuracy at normal electrolyte levels.\",\"Quality Control Material \\u2013 High\\/Abnormal Level \\u2014 control solution for higher electrolyte values.\",\"Daily Cleaning Solution \\u2014 reagent used to clean fluid pathways and maintain sensor performance.\",\"Multi\\u2011Biosensor Module(s) (electrode\\/biosensor cartridges) \\u2014 maintenance\\u2011free sensor modules that interact with reagents to detect ions (Na\\u207a, K\\u207a, Cl\\u207b, Ca\\u00b2\\u207a, pH).\",\"Waste Collection Component (part of the reagent pack design) \\u2014 collects spent reagent fluid safely.\",\"Printer Consumables (Thermal Printer Paper) \\u2014 paper rolls used for the built\\u2011in printer to output results.\"]', '[\"products\\/g1wpkQMGvEaUhd4udU4XbV1HPBffNaIO09pbV9zE.jpg\"]', 'products/g1wpkQMGvEaUhd4udU4XbV1HPBffNaIO09pbV9zE.jpg', 0, NULL, '2026-02-12 15:36:17', '2026-02-12 15:36:32', NULL),
(28, 'EDAN I15', 'chemistry', 'The EDAN i15 is a portable blood gas and chemistry analyzer designed for point‑of‑care testing (POCT) in critical care, emergency, ICU, and clinical settings. It uses single‑use disposable cartridges (also called reagent packs) that contain all necessary reagents and sensors for measuring blood gases, electrolytes, metabolites, and hematocrit from a small whole‑blood sample — with results in about 1 minute after sample aspiration.', '[\"Sample: 140\\u202f\\u00b5L whole blood (arterial, venous, capillary)\",\"Analysis time: ~60\\u202fs\",\"Parameters: pH, pO\\u2082, pCO\\u2082, Na\\u207a, K\\u207a, Cl\\u207b, Ca\\u00b2\\u207a, Glucose, Lactate, Hematocrit\",\"Display: 7\\u2033 color touchscreen\",\"Power: 100\\u2013240\\u202fV AC \\/ built-in rechargeable battery (~50 tests\\/charge)\",\"Connectivity: USB, RS\\u2011232, LAN, Wi\\u2011Fi, barcode scanner\",\"Printer: Built-in thermal\",\"Storage: Up to ~10,000 results\",\"Size & weight: 238\\u202f\\u00d7\\u202f153\\u202f\\u00d7\\u202f310\\u202fmm, ~3.65\\u202fkg\"]', '[\"\\u2022 Portable & lightweight design with built\\u2011in rechargeable battery, printer, and barcode scanner \\u2014 ideal for point\\u2011of\\u2011care use at the bedside, emergency, ICU, or field settings.\",\"\\u2022 Fast, multi\\u2011parameter testing from a single disposable cartridge \\u2014 results in \\u22481 minute after sample aspiration.\",\"\\u2022 Zero routine maintenance thanks to disposable reagent\\/test cartridges and auto sample aspiration.\",\"\\u2022 Multi\\u2011parameter capability covering blood gases, electrolytes, metabolites, and hematocrit in one run.\",\"\\u2022 User\\u2011friendly 7\\u2033 color touchscreen interface with intuitive menus and multimedia tutorials.\",\"\\u2022 Strong data management with storage for up to 10,000 results and connectivity (USB\\/RS232\\/LAN\\/Wi\\u2011Fi).\",\"\\u2022 Advanced quality control including internal QC, calibrator, and electronic simulator for reliable performance.\",\"\\u2022 Disposable cartridges reduce biohazard risk and streamline workflow.\"]', '[\"\\u2022 Rapid bedside\\/POCT measurement of pH, pO\\u2082, pCO\\u2082, sodium (Na\\u207a), potassium (K\\u207a), chloride (Cl\\u207b), calcium (Ca\\u00b2\\u207a), glucose (Glu), lactate (Lac), and hematocrit (Hct) from arterial, venous, or capillary whole blood.\",\"\\u2022 Provides critical information on acid\\u2011base balance, gas exchange, electrolytes, metabolic status, and oxygenation for patient management.\"]', '[]', '[\"\\u2022 EU IVDR Class C (CE\\u2011IVD) \\u2014 certified under the European Union In Vitro Diagnostics Regulation (IVDR) as a Class C near\\u2011patient testing device, showing compliance with stringent EU regulatory requirements.\",\"\\u2022 CE Mark \\u2014 the device and its blood gas products carry CE marking for in\\u2011vitro diagnostic use in the European market.\",\"\\u2022 ISO 13485 \\u2014 manufactured under an ISO\\u202f13485 quality management system for medical devices.\",\"\\u2022 FDA 510(k) clearance \\u2014 cleared in the U.S. as a blood gas and chemistry analysis system for multiple parameters (pH, pCO\\u2082, pO\\u2082, Na\\u207a, K\\u207a, Cl\\u207b, Ca\\u00b2\\u207a and hematocrit)\"]', '[\"BG3 cartridge \\u2014 pH, pCO\\u2082, pO\\u2082\",\"BG4 cartridge \\u2014 pH, pCO\\u2082, pO\\u2082, Lactate (Lac)\",\"BC4 cartridge \\u2014 Na\\u207a, K\\u207a, Cl\\u207b, Ca\\u00b2\\u207a, Hematocrit (Hct)\",\"BG8 cartridge \\u2014 pH, pCO\\u2082, pO\\u2082, Na\\u207a, K\\u207a, Cl\\u207b, Ca\\u00b2\\u207a, Hematocrit (Hct)\",\"BG9 cartridge \\u2014 pH, pCO\\u2082, pO\\u2082, Na\\u207a, K\\u207a, Cl\\u207b, Ca\\u00b2\\u207a, Hematocrit (Hct), Glucose (Glu)\",\"BG10 cartridge \\u2014 pH, pCO\\u2082, pO\\u2082, Na\\u207a, K\\u207a, Cl\\u207b, Ca\\u00b2\\u207a, Hematocrit (Hct), Glucose (Glu), Lactate (Lac)\"]', '[\"products\\/smd9lXbrDjoMMBsmXLe3dLzRr361dWOH3eUGfGwe.png\"]', 'products/smd9lXbrDjoMMBsmXLe3dLzRr361dWOH3eUGfGwe.png', 0, NULL, '2026-02-12 15:43:43', '2026-02-12 15:44:55', NULL);
